"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";
import { AuthGuard } from "../components/AuthGuard";
import Sidebar from "../components/Sidebar";
import KanbanBoard from "../components/KanbanBoard";
import { apiFetch, API_BASE_URL } from "../services/api";
import { Bar, BarChart, Cell, Legend, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";

const api = API_BASE_URL;
type Client = { id: number; name: string; location: string };
type Meeting = { id: number; client_id: number; title: string; scheduled_for: string; created_at: string | null; agenda: string; attendees: string; notes: string; mom?: string | null };
type Action = { id: number; client_id: number; title: string; owner: string; due_date: string; priority: string; status: string; meeting_id: number | null; assigned_to?: number | null };
type Feature = { id: number; client_id: number; name: string; developer: string; sprint: string; progress: number; target_date: string; dependency: string | null };
type Requirement = { id: number; client_id: number; title: string; source: string; requirement_type: string; business_objective: string; description: string; acceptance_criteria: string; priority: string; status: string; owner: string; target_date: string | null; dependencies: string; notes: string; created_at: string; updated_at: string };
type Dashboard = { meetings: Meeting[]; actions: Action[]; features: Feature[]; requirements: Requirement[] };
type PersonalDashboard = { summary: { total_action_items: number; total_change: number; on_track: number; at_risk: number; overdue: number; completed: number }; module_breakdown: { name: string; count: number }[]; eda_performance: { on_or_before: number; completed_after: number; not_completed: number }; recent_items: { id: number; title: string; module: string; status: string }[]; upcoming_deadlines: { title: string; module: string; eda: string }[]; discussion_summary: { total: number; recent: { id: number; title: string; summary: string }[] }; meeting_summary: { total: number; upcoming: number; completed: number } };
const empty: Dashboard = { meetings: [], actions: [], features: [], requirements: [] };

function HomeContent() {
  const [clients, setClients] = useState<Client[]>([]); const [data, setData] = useState<Dashboard>(empty); const [personal, setPersonal] = useState<PersonalDashboard | null>(null); const [notice, setNotice] = useState(""); const [module, setModule] = useState<"dashboard" | "meetings" | "development" | "requirements" | "action-items" | "my-work" | "client-view" | "executive" | "master" | "qa" | "admin">("dashboard"); const [dashboardClientId, setDashboardClientId] = useState(""); const [dashboardMeetingId, setDashboardMeetingId] = useState(""); const [dashboardMeetingDate, setDashboardMeetingDate] = useState(""); const [meetingClientId, setMeetingClientId] = useState(""); const [developmentClientId, setDevelopmentClientId] = useState(""); const [requirementsClientId, setRequirementsClientId] = useState(""); const [meetingDate, setMeetingDate] = useState("");
  const load = async () => { const response = await apiFetch("/dashboard"); if (!response.ok) throw new Error("Unable to load dashboard"); const payload = await response.json(); if (!payload || !Array.isArray(payload.meetings) || !Array.isArray(payload.actions) || !Array.isArray(payload.features) || !Array.isArray(payload.requirements)) throw new Error("Invalid dashboard response"); setData(payload); };
  useEffect(() => { apiFetch("/clients").then(async response => { if (!response.ok) throw new Error("Unable to load clients"); const payload = await response.json(); if (!Array.isArray(payload)) throw new Error("Invalid clients response"); setClients(payload); }).catch(() => { setClients([]); setNotice("Unable to load clients. Please sign in again or start the FastAPI service."); }); }, []);
  useEffect(() => { load().catch(() => undefined); }, []);
  useEffect(() => { const refresh = () => { load().catch(() => undefined); }; window.addEventListener("deliveryhub-refresh", refresh); return () => window.removeEventListener("deliveryhub-refresh", refresh); }, []);
  useEffect(() => { apiFetch("/dashboards/personal").then(response => response.ok ? response.json() : null).then(setPersonal).catch(() => undefined); }, [data.actions.length, data.meetings.length]);
  const selectedDashboard = clients.find(client => String(client.id) === dashboardClientId);
  const selectedMeeting = clients.find(client => String(client.id) === meetingClientId);
  const selectedDevelopment = clients.find(client => String(client.id) === developmentClientId);
  const actionsByMeeting = useMemo(() => {
    const grouped = new Map<number, Action[]>();
    data.actions.filter(action => action.meeting_id).forEach(action => grouped.set(action.meeting_id!, [...(grouped.get(action.meeting_id!) || []), action]));
    return grouped;
  }, [data.actions]);

  async function submit(event: FormEvent<HTMLFormElement>, endpoint: string) { event.preventDefault(); const formElement = event.currentTarget; const form = new FormData(formElement); const payload = Object.fromEntries(form.entries()) as Record<string, string | null>; if (payload.meeting_id === "") payload.meeting_id = null; if (!payload.client_id) { setNotice("Select Finkomm or HHP before saving."); return; } const response = await apiFetch(endpoint, { method: "POST", body: JSON.stringify(payload) }); if (!response.ok) { setNotice("Could not save. Please check the fields and API service."); return; } formElement.reset(); setNotice("Saved successfully."); load(); }
  async function updateProgress(id: number, progress: number) { const response = await apiFetch(`/features/${id}/progress?progress=${progress}`, { method: "PATCH" }); if (!response.ok) { setNotice(response.status === 401 ? "Your session has expired. Please sign in again." : "Could not update progress."); return; } const updated: Feature = await response.json(); setData(previous => ({ ...previous, features: previous.features.map(feature => feature.id === id ? updated : feature) })); setNotice("Progress updated."); }
  async function deleteFeature(id: number, name: string) { if (!window.confirm(`Delete “${name}” from the development pipeline?`)) return; const response = await fetch(`${api}/features/${id}`, { method: "DELETE" }); if (!response.ok) { setNotice("Could not delete this development item."); return; } setData(previous => ({ ...previous, features: previous.features.filter(feature => feature.id !== id) })); setNotice("Development item deleted."); }
  async function updateMeeting(id: number, payload: Record<string, string>) { const response = await apiFetch(`/meetings/${id}`, { method: "PATCH", body: JSON.stringify(payload) }); if (!response.ok) { setNotice(response.status === 401 ? "Your session has expired. Please sign in again." : "This meeting is no longer within its 48-hour edit window."); return null; } const updated: Meeting = await response.json(); setData(previous => ({ ...previous, meetings: previous.meetings.map(meeting => meeting.id === id ? updated : meeting) })); setNotice("Meeting updated."); return updated; }
  async function deleteMeeting(id: number, title: string) { if (!window.confirm(`Delete “${title}”? Linked action items will be kept without the meeting link.`)) return; const response = await fetch(`${api}/meetings/${id}`, { method: "DELETE" }); if (!response.ok) { setNotice("Could not delete this meeting."); return; } setData(previous => ({ ...previous, meetings: previous.meetings.filter(meeting => meeting.id !== id), actions: previous.actions.map(action => action.meeting_id === id ? { ...action, meeting_id: null } : action) })); setNotice("Meeting deleted."); }
  async function updateAction(id: number, payload: Record<string, string | null>) { const response = await apiFetch(`/actions/${id}`, { method: "PATCH", body: JSON.stringify(payload) }); if (!response.ok) { setNotice(response.status === 401 ? "Your session has expired. Please sign in again." : "Could not update this action item."); return null; } const updated: Action = await response.json(); setData(previous => ({ ...previous, actions: previous.actions.map(action => action.id === id ? updated : action) })); setNotice("Action item updated."); return updated; }
  async function deleteAction(id: number, title: string) { if (!window.confirm(`Delete action item “${title}”?`)) return; const response = await fetch(`${api}/actions/${id}`, { method: "DELETE" }); if (!response.ok) { setNotice("Could not delete this action item."); return; } setData(previous => ({ ...previous, actions: previous.actions.filter(action => action.id !== id) })); setNotice("Action item deleted."); }

  return <><Sidebar active={module} onSelect={setModule}/><main className="app-shell min-h-screen bg-[#f5f7fb]"><div className="mx-auto max-w-7xl px-5 py-6 md:px-8 md:py-8">
    <header className="hero-panel overflow-hidden rounded-3xl px-6 py-7 text-white md:px-9"><div className="relative z-10"><div className="mb-4 flex items-center gap-3"><span className="brand-mark">DH</span><span className="text-sm font-medium tracking-[0.18em] text-indigo-100">DELIVERY HUB</span></div><h1 className="text-3xl font-semibold tracking-tight md:text-4xl">Project delivery, clearly organised.</h1><p className="mt-3 max-w-xl text-sm leading-6 text-indigo-100">A complete meeting history and a live development pipeline for Finkomm and HHP.</p></div></header>
    {notice && <p className="notice mt-4">{notice}</p>}
    {module === "dashboard" ? <DashboardModule clients={clients} clientId={dashboardClientId} setClientId={setDashboardClientId} selectedName={selectedDashboard?.name} data={data} personal={personal} actionsByMeeting={actionsByMeeting} meetingId={dashboardMeetingId} setMeetingId={setDashboardMeetingId} meetingDate={dashboardMeetingDate} setMeetingDate={setDashboardMeetingDate}/> : module === "meetings" ? <MeetingsModule clients={clients} clientId={meetingClientId} setClientId={setMeetingClientId} selectedName={selectedMeeting?.name} data={data} actionsByMeeting={actionsByMeeting} meetingDate={meetingDate} setMeetingDate={setMeetingDate} submit={submit} updateMeeting={updateMeeting} deleteMeeting={deleteMeeting} updateAction={updateAction} deleteAction={deleteAction}/> : module === "my-work" ? <MyWorkModule clients={clients} setData={setData} setNotice={setNotice}/> : module === "client-view" ? <ClientDashboardModule clients={clients}/> : module === "executive" ? <ExecutiveDashboardModule/> : module === "master" ? <MasterControlModule/> : module === "qa" ? <QADashboardModule/> : module === "admin" ? <AdminRbacModule/> : module === "action-items" ? <ActionItemsModule clients={clients} actions={data.actions} setData={setData} setNotice={setNotice}/> : module === "development" ? <DevelopmentModule clients={clients} clientId={developmentClientId} setClientId={setDevelopmentClientId} selectedName={selectedDevelopment?.name} features={data.features} submit={submit} updateProgress={updateProgress} deleteFeature={deleteFeature}/> : <RequirementsModule clients={clients} clientId={requirementsClientId} setClientId={setRequirementsClientId} selectedName={clients.find(client => String(client.id) === requirementsClientId)?.name} requirements={data.requirements} submit={submit} setData={setData}/>} 
  </div></main></>;
}

export default function Home() { return <AuthGuard><HomeContent /></AuthGuard>; }

function MyWorkModule({ clients, setData, setNotice }: { clients: Client[]; setData: React.Dispatch<React.SetStateAction<Dashboard>>; setNotice: (message: string) => void }) {
  const [items, setItems] = useState<Action[]>([]); const [userName, setUserName] = useState("there");
  useEffect(() => { try { const stored = JSON.parse(localStorage.getItem("deliveryhub_user") || "null"); if (stored?.id) { setUserName(stored.name || "there"); apiFetch(`/action-items?assigned_to=${stored.id}`).then(response => response.ok ? response.json() : []).then(setItems).catch(() => undefined); } } catch { /* ignore malformed local session */ } }, []);
  const count = (statuses: string[]) => items.filter(item => statuses.includes(item.status.toLowerCase())).length;
  const syncSetData: React.Dispatch<React.SetStateAction<Dashboard>> = updater => { setData(updater); if (typeof updater === "function") setItems(previous => updater({ meetings: [], actions: previous, features: [], requirements: [] }).actions); };
  return <section className="mt-6"><div><p className="eyebrow">Developer dashboard</p><h2 className="text-2xl font-semibold tracking-tight">Welcome back, {userName}</h2><p className="mt-1 text-sm text-slate-500">Your assigned work across the delivery workspace.</p></div><div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><SummaryCard label="My open tasks" value={count(["open", "to do", "todo"])} tone="indigo"/><SummaryCard label="In progress" value={count(["in progress", "in-progress"])} tone="emerald"/><SummaryCard label="Blocked" value={count(["blocked"])} tone="rose"/><SummaryCard label="Completed" value={count(["done", "completed", "closed"])} tone="violet"/></div><div className="mt-6"><ActionItemsModule clients={clients} actions={items} setData={syncSetData} setNotice={setNotice}/></div></section>;
}

function ClientDashboardModule({ clients }: { clients: Client[] }) { const [clientId, setClientId] = useState(clients[0] ? String(clients[0].id) : ""); const [dashboard, setDashboard] = useState<any>(null); const [loading, setLoading] = useState(false); useEffect(() => { if (!clientId) return; setLoading(true); apiFetch(`/projects?client_id=${clientId}`).then(response => response.json()).then(projects => projects[0]?.id ? apiFetch(`/dashboards/client?project_id=${projects[0].id}`).then(response => response.json()).then(setDashboard) : setDashboard(null)).catch(() => setDashboard(null)).finally(() => setLoading(false)); }, [clientId]); return <section className="mt-6"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Client dashboard</p><h2 className="text-2xl font-semibold tracking-tight">Delivery progress</h2><p className="mt-1 text-sm text-slate-500">A clear, client-friendly view of commitments and upcoming milestones.</p></div><label className="module-filters">Client<select value={clientId} onChange={event => setClientId(event.target.value)}>{clients.map(client => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label></div>{loading ? <div className="surface-card mt-6 p-8 text-center text-slate-500">Loading delivery progress…</div> : dashboard ? <><article className="client-progress-hero mt-6"><div><p className="text-sm font-medium text-slate-500">Overall progress</p><p className="mt-1 text-5xl font-semibold text-slate-900">{dashboard.progress}%</p><p className="mt-2 text-sm text-slate-500">{dashboard.completed_tasks} of {dashboard.total_tasks} delivery items completed</p></div><div className="client-progress-ring" style={{ "--progress": `${dashboard.progress * 3.6}deg` } as React.CSSProperties}><strong>{dashboard.progress}%</strong></div></article><div className="mt-5 grid gap-4 sm:grid-cols-3"><SummaryCard label="Upcoming deliverables" value={dashboard.upcoming_deliverables.length} tone="indigo"/><SummaryCard label="Pending approvals" value={dashboard.pending_approvals.length} tone="amber"/><SummaryCard label="Meetings this month" value={dashboard.meetings.this_month} tone="emerald"/></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><article className="surface-card p-6"><p className="eyebrow">Upcoming deliverables</p><div className="mt-4 space-y-3">{dashboard.upcoming_deliverables.length ? dashboard.upcoming_deliverables.map((item: any) => <div className="dashboard-action" key={item.id}><span>{item.title}</span><span className="soft-pill">{item.eda}</span></div>) : <p className="text-sm text-slate-500">No upcoming deliverables scheduled.</p>}</div></article><article className="surface-card p-6"><p className="eyebrow">Recent deliveries</p><div className="mt-4 space-y-3">{dashboard.recent_deliveries.length ? dashboard.recent_deliveries.map((item: any) => <div className="dashboard-action" key={item.id}><span>{item.title}</span><span className="text-xs text-slate-500">Completed</span></div>) : <p className="text-sm text-slate-500">No recent deliveries recorded.</p>}</div></article></div>{dashboard.pending_approvals.length > 0 && <article className="client-approval-panel mt-5"><p className="eyebrow">Pending approvals</p><div className="mt-3 space-y-2">{dashboard.pending_approvals.map((item: any) => <p key={item.id} className="text-sm text-amber-900">{item.title}</p>)}</div></article>}{dashboard.meetings.next && <article className="client-next-meeting mt-5"><div><p className="eyebrow">Next meeting</p><h3 className="mt-1 font-semibold text-blue-900">{dashboard.meetings.next.title}</h3></div><span>{new Date(dashboard.meetings.next.scheduled_at).toLocaleString()}</span></article>}</> : <article className="surface-card mt-6 p-8 text-center text-slate-500">No client project is available for this account.</article>}</section>; }

function ExecutiveDashboardModule() { const [dashboard, setDashboard] = useState<any>(null); const [error, setError] = useState(false); useEffect(() => { apiFetch("/dashboards/executive").then(response => response.ok ? response.json() : Promise.reject()).then(setDashboard).catch(() => setError(true)); }, []); if (error) return <article className="surface-card mt-6 p-8 text-center text-slate-600">Executive dashboard access is restricted to administrators and management users.</article>; if (!dashboard) return <article className="surface-card mt-6 p-8 text-center text-slate-500">Loading executive overview…</article>; const summary = dashboard.summary; return <section className="mt-6"><div><p className="eyebrow">Executive dashboard</p><h2 className="text-2xl font-semibold tracking-tight">Portfolio command centre</h2><p className="mt-1 text-sm text-slate-500">A cross-client view of delivery health, workload, and recent activity.</p></div><div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><SummaryCard label="Projects" value={summary.total_projects} tone="indigo"/><SummaryCard label="Action items" value={summary.total_action_items} tone="amber"/><SummaryCard label="Overall progress" value={`${summary.overall_progress}%`} tone="emerald"/><SummaryCard label="Overdue" value={summary.overdue} tone="rose"/><SummaryCard label="Blocked" value={summary.blocked} tone="violet"/></div><article className="surface-card mt-6 overflow-hidden"><div className="border-b border-slate-100 p-5"><p className="eyebrow">Project health</p><h3 className="mt-1 text-lg font-semibold">Portfolio status</h3></div><div className="divide-y divide-slate-100">{dashboard.project_health.length ? dashboard.project_health.map((project: any) => <div className="grid gap-3 p-5 md:grid-cols-[1.4fr_.8fr_1fr_.5fr_.5fr_auto] md:items-center"><div><p className="font-medium">{project.project_name}</p><p className="text-xs text-slate-500">{project.client_name}</p></div><span className="text-sm font-semibold">{project.progress}% complete</span><div className="progress-track progress-indigo"><div style={{ width: `${project.progress}%` }}/></div><span className="text-sm text-rose-600">{project.overdue} overdue</span><span className="text-sm text-amber-600">{project.blocked} blocked</span><span className={`status-pill status-${project.health === "critical" ? "red" : project.health === "warning" ? "orange" : "emerald"}`}>{project.health}</span></div>) : <p className="p-6 text-sm text-slate-500">No projects found.</p>}</div></article><div className="mt-6 grid gap-5 lg:grid-cols-2"><article className="surface-card p-5"><p className="eyebrow">Team workload</p><div className="mt-3 space-y-3">{dashboard.team_workload.length ? dashboard.team_workload.map((item: any) => <div className="dashboard-action" key={item.user_id}><span>{item.user_name}</span><strong>{item.task_count} active tasks</strong></div>) : <p className="text-sm text-slate-500">No active assignments.</p>}</div></article><article className="surface-card p-5"><p className="eyebrow">Recent activity</p><div className="mt-3 space-y-3">{dashboard.recent_activity.length ? dashboard.recent_activity.slice(0, 6).map((item: any) => <div className="dashboard-action" key={item.id}><span>{item.title}</span><span className="soft-pill">{item.status}</span></div>) : <p className="text-sm text-slate-500">No recent activity.</p>}</div></article></div></section>; }

function MasterControlModule() { const [dashboard, setDashboard] = useState<any>(null); const [restricted, setRestricted] = useState(false); useEffect(() => { apiFetch("/dashboards/master").then(response => response.ok ? response.json() : Promise.reject()).then(setDashboard).catch(() => setRestricted(true)); }, []); if (restricted) return <article className="surface-card mt-6 p-8 text-center text-slate-600">Master Control is restricted to NorQ internal management.</article>; if (!dashboard) return <article className="surface-card mt-6 p-8 text-center text-slate-500">Loading Master Control…</article>; const summary = dashboard.summary; return <section className="mt-6"><div><p className="eyebrow">NorQ operational view</p><h2 className="text-2xl font-semibold tracking-tight">Master Control Tower</h2><p className="mt-1 text-sm text-slate-500">Real-time operational pulse across all client projects.</p></div><div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><SummaryCard label="Projects" value={summary.total_projects} tone="indigo"/><SummaryCard label="Open tasks" value={summary.open_tasks} tone="amber"/><SummaryCard label="Total tasks" value={summary.total_tasks} tone="violet"/><SummaryCard label="Overdue" value={summary.overdue} tone="rose"/><SummaryCard label="Critical" value={summary.critical} tone="orange"/></div><article className="surface-card mt-6 overflow-hidden"><div className="border-b border-slate-100 p-5"><p className="eyebrow">Project snapshot</p><h3 className="mt-1 text-lg font-semibold">Portfolio operating status</h3></div><div className="divide-y divide-slate-100">{dashboard.projects.map((project: any) => <div className="grid gap-3 p-5 md:grid-cols-[1.3fr_.8fr_.8fr_1fr_.5fr_.5fr] md:items-center" key={project.id}><div><p className="font-medium">{project.name}</p><p className="text-xs text-slate-500">{project.client} · PM {project.pm}</p></div><span className="text-sm">{project.progress}% complete</span><div className="progress-track progress-indigo"><div style={{ width: `${project.progress}%` }}/></div><span className="text-sm text-rose-600">{project.overdue} overdue</span><span className="text-sm text-amber-600">{project.blocked} blocked</span><span className="text-xs text-slate-500">{project.completed}/{project.total} done</span></div>)}</div></article><div className="mt-6 grid gap-5 lg:grid-cols-3"><article className="surface-card p-5 lg:col-span-1"><p className="eyebrow">Urgent actions</p><div className="mt-3 space-y-3">{dashboard.urgent_actions.length ? dashboard.urgent_actions.slice(0, 8).map((item: any) => <div className="dashboard-action" key={item.id}><div><p className="font-medium">{item.title}</p><p className="text-xs text-slate-500">{item.project}</p></div><span className="priority-dot priority-high">{item.priority}</span></div>) : <p className="text-sm text-slate-500">No urgent actions.</p>}</div></article><article className="surface-card p-5 lg:col-span-1"><p className="eyebrow">Upcoming deadlines</p><div className="mt-3 space-y-3">{dashboard.upcoming_deadlines.length ? dashboard.upcoming_deadlines.slice(0, 8).map((item: any) => <div className="dashboard-action" key={item.id}><span>{item.title}</span><span className="soft-pill">{item.eda}</span></div>) : <p className="text-sm text-slate-500">No deadlines in the next 14 days.</p>}</div></article><article className="surface-card p-5 lg:col-span-1"><p className="eyebrow">Resource load</p><div className="mt-3 space-y-3">{dashboard.resource_allocation.length ? dashboard.resource_allocation.slice(0, 8).map((item: any) => <div key={item.user_id}><div className="flex justify-between text-sm"><span>{item.user_name}</span><strong>{item.task_count}</strong></div><div className="progress-track progress-indigo"><div style={{ width: `${Math.min(100, item.task_count / 15 * 100)}%` }}/></div></div>) : <p className="text-sm text-slate-500">No active assignments.</p>}</div></article></div></section>; }

function QADashboardModule() { const [dashboard, setDashboard] = useState<any>(null); const [restricted, setRestricted] = useState(false); useEffect(() => { apiFetch("/dashboards/qa").then(response => response.ok ? response.json() : Promise.reject()).then(setDashboard).catch(() => setRestricted(true)); }, []); if (restricted) return <article className="surface-card mt-6 p-8 text-center text-slate-600">QA Dashboard is restricted to internal users.</article>; if (!dashboard) return <article className="surface-card mt-6 p-8 text-center text-slate-500">Loading QA Dashboard…</article>; const summary = dashboard.summary; const list = (items: any[], empty: string) => items.length ? <div className="mt-3 space-y-2">{items.slice(0, 8).map(item => <div className="dashboard-action" key={item.id}><div><p className="font-medium">{item.title}</p><p className="text-xs text-slate-500">{item.project} · {item.assigned_to || "Unassigned"}</p></div><span className="soft-pill">{item.priority || item.status || "Ready"}</span></div>)}</div> : <p className="mt-3 text-sm text-slate-500">{empty}</p>; return <section className="mt-6"><div><p className="eyebrow">Testing command center</p><h2 className="text-2xl font-semibold tracking-tight">QA Dashboard</h2><p className="mt-1 text-sm text-slate-500">Testing queue, failures, critical bugs, and UAT readiness.</p></div><div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><SummaryCard label="Testing queue" value={summary.testing_queue} tone="violet"/><SummaryCard label="Failed tests" value={summary.failed_tests} tone="rose"/><SummaryCard label="Critical bugs" value={summary.critical_bugs} tone="red"/><SummaryCard label="Ready for UAT" value={summary.ready_for_uat} tone="emerald"/></div><div className="mt-6 grid gap-5 lg:grid-cols-2"><article className="surface-card p-5"><p className="eyebrow">Testing queue</p>{list(dashboard.testing_queue, "Testing queue is empty.")}</article><article className="surface-card p-5"><p className="eyebrow">Failed tests</p>{list(dashboard.failed_tests, "No failed tests.")}</article><article className="surface-card p-5"><p className="eyebrow">Critical bugs</p>{list(dashboard.critical_bugs, "No critical bugs.")}</article><article className="surface-card p-5"><p className="eyebrow">Ready for UAT</p>{list(dashboard.ready_for_uat, "No items ready for UAT.")}</article></div><article className="surface-card mt-5 p-5"><p className="eyebrow">Recent QA activity</p>{list(dashboard.recent_activity, "No recent QA activity.")}</article></section>; }

function AdminRbacModule() { const modules = ["Action Items", "Meetings", "Discussions", "Reports", "Users", "Projects", "Clients", "Modules", "Dashboards"]; const [roles, setRoles] = useState<any[]>([]); const [users, setUsers] = useState<any[]>([]); const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [selectedModules, setSelectedModules] = useState<string[]>([]); const load = () => Promise.all([apiFetch("/roles"), apiFetch("/users")]).then(async ([rolesResponse, usersResponse]) => { if (!rolesResponse.ok || !usersResponse.ok) throw new Error(); setRoles(await rolesResponse.json()); setUsers(await usersResponse.json()); }).catch(() => undefined); useEffect(() => { load(); }, []); const createRole = async (event: FormEvent) => { event.preventDefault(); const permissions = Object.fromEntries(modules.map(module => [module, Object.fromEntries(["create", "read", "update", "delete", "view"].map(action => [action, selectedModules.includes(module)]))])); const response = await apiFetch("/roles", { method: "POST", body: JSON.stringify({ name, description, permissions }) }); if (response.ok) { setName(""); setDescription(""); setSelectedModules([]); load(); } }; const assign = async (userId: number, roleId: string) => { const response = await apiFetch(`/users/${userId}/role`, { method: "PATCH", body: JSON.stringify({ role_id: Number(roleId) }) }); if (response.ok) load(); }; return <section className="mt-6"><div><p className="eyebrow">Administration</p><h2 className="text-2xl font-semibold tracking-tight">Roles and permissions</h2><p className="mt-1 text-sm text-slate-500">Create custom roles and assign access without changing code.</p></div><div className="mt-5 grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><form className="surface-card space-y-4 p-5" onSubmit={createRole}><div><p className="eyebrow">New custom role</p><h3 className="text-lg font-semibold">Permission profile</h3></div><label>Name<input value={name} onChange={event => setName(event.target.value)} required placeholder="Project Lead"/></label><label>Description<textarea value={description} onChange={event => setDescription(event.target.value)} placeholder="What this role can do"/></label><div><p className="detail-label">Modules with full CRUDV access</p><div className="mt-2 grid grid-cols-2 gap-2">{modules.map(module => <label className="flex items-center gap-2 rounded-lg bg-slate-50 p-2 text-xs" key={module}><input type="checkbox" checked={selectedModules.includes(module)} onChange={event => setSelectedModules(previous => event.target.checked ? [...previous, module] : previous.filter(item => item !== module))}/>{module}</label>)}</div></div><button>Create role</button></form><div className="space-y-5"><article className="surface-card p-5"><p className="eyebrow">Available roles</p><div className="mt-3 space-y-2">{roles.map(role => <div className="dashboard-action" key={role.id}><div><p className="font-medium">{role.name}</p><p className="text-xs text-slate-500">{role.description || "No description"}</p></div><span className="soft-pill">{role.is_system ? "System" : "Custom"}</span></div>)}</div></article><article className="surface-card p-5"><p className="eyebrow">User assignments</p><div className="mt-3 space-y-2">{users.map(item => <div className="dashboard-action" key={item.id}><div><p className="font-medium">{item.name}</p><p className="text-xs text-slate-500">{item.email}</p></div><select value={item.role_id || ""} onChange={event => assign(item.id, event.target.value)}><option value="" disabled>{item.role}</option>{roles.map(role => <option value={role.id} key={role.id}>{role.name}</option>)}</select></div>)}</div></article></div></div></section>; }

function RbacMatrixModule() { const modules = ["Action Items", "Meetings", "Discussions", "Reports", "Users", "Projects", "Clients", "Modules", "Dashboards"]; const actions = ["create", "read", "update", "delete", "view"]; const blank = () => Object.fromEntries(modules.map(module => [module, Object.fromEntries(actions.map(action => [action, false]))])); const [roles, setRoles] = useState<any[]>([]); const [users, setUsers] = useState<any[]>([]); const [editing, setEditing] = useState<any>(null); const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [permissions, setPermissions] = useState<any>(blank()); const load = () => Promise.all([apiFetch("/roles"), apiFetch("/users")]).then(async ([rolesResponse, usersResponse]) => { if (!rolesResponse.ok || !usersResponse.ok) throw new Error(); setRoles(await rolesResponse.json()); setUsers(await usersResponse.json()); }).catch(() => undefined); useEffect(() => { load(); }, []); const startNew = () => { setEditing(null); setName(""); setDescription(""); setPermissions(blank()); }; const editRole = (role: any) => { setEditing(role); setName(role.name); setDescription(role.description || ""); const matrix = blank(); modules.forEach(module => actions.forEach(action => { matrix[module][action] = Boolean(role.permissions?.[module]?.[action]); })); setPermissions(matrix); }; const toggle = (module: string, action: string) => setPermissions((previous: any) => ({ ...previous, [module]: { ...previous[module], [action]: !previous[module][action] } })); const save = async (event: FormEvent) => { event.preventDefault(); const response = editing ? await apiFetch(`/roles/${editing.id}`, { method: "PATCH", body: JSON.stringify({ description, permissions }) }) : await apiFetch("/roles", { method: "POST", body: JSON.stringify({ name, description, permissions }) }); if (response.ok) { startNew(); load(); } }; const assign = async (userId: number, roleId: string) => { const response = await apiFetch(`/users/${userId}/role`, { method: "PATCH", body: JSON.stringify({ role_id: Number(roleId) }) }); if (response.ok) load(); }; return <section className="mt-6"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Administration</p><h2 className="text-2xl font-semibold tracking-tight">Custom roles and CRUDV permissions</h2><p className="mt-1 text-sm text-slate-500">Set each Create, Read, Update, Delete, and View permission independently for every module.</p></div>{editing && <button type="button" className="clear-filter" onClick={startNew}>New role</button>}</div><form className="surface-card mt-5 p-5" onSubmit={save}><div className="grid gap-4 sm:grid-cols-2"><label>Role name<input value={name} onChange={event => setName(event.target.value)} required disabled={Boolean(editing?.is_system)} placeholder="Project Lead"/></label><label>Description<input value={description} onChange={event => setDescription(event.target.value)} placeholder="Role responsibilities"/></label></div><div className="mt-5 overflow-x-auto"><table className="rbac-matrix"><thead><tr><th>Module</th>{actions.map(action => <th key={action}>{action[0].toUpperCase()}</th>)}</tr></thead><tbody>{modules.map(module => <tr key={module}><td>{module}</td>{actions.map(action => <td key={action}><input aria-label={`${module} ${action}`} type="checkbox" checked={Boolean(permissions[module][action])} onChange={() => toggle(module, action)}/></td>)}</tr>)}</tbody></table></div><button className="mt-5">{editing ? "Save permission changes" : "Create custom role"}</button></form><div className="mt-5 grid gap-5 lg:grid-cols-2"><article className="surface-card p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Roles</p><h3 className="text-lg font-semibold">Permission profiles</h3></div><span className="soft-pill">{roles.length}</span></div><div className="mt-3 space-y-2">{roles.map(role => <div className="dashboard-action" key={role.id}><div><p className="font-medium">{role.name}</p><p className="text-xs text-slate-500">{role.description || "No description"}</p></div><button type="button" className="edit-button" onClick={() => editRole(role)}>Edit matrix</button></div>)}</div></article><article className="surface-card p-5"><p className="eyebrow">User role assignment</p><div className="mt-3 space-y-2">{users.map(item => <div className="dashboard-action" key={item.id}><div><p className="font-medium">{item.name}</p><p className="text-xs text-slate-500">{item.email}</p></div><select value={item.role_id || ""} onChange={event => assign(item.id, event.target.value)}><option value="" disabled>{item.role}</option>{roles.map(role => <option value={role.id} key={role.id}>{role.name}</option>)}</select></div>)}</div></article></div></section>; }

// Replace the initial coarse module selector with the full CRUDV matrix editor.
// @ts-ignore Runtime presentation replacement.
AdminRbacModule = function RbacMatrixWrapper() { return <RbacMatrixModule/>; };

function ActionItemsModule({ clients, actions, setData, setNotice }: { clients: Client[]; actions: Action[]; setData: React.Dispatch<React.SetStateAction<Dashboard>>; setNotice: (message: string) => void }) {
  const [clientId, setClientId] = useState(clients[0] ? String(clients[0].id) : "");
  const [showCreate, setShowCreate] = useState(false);
  useEffect(() => { if (!clientId && clients[0]) setClientId(String(clients[0].id)); }, [clients, clientId]);
  const columns = ["Open", "In Progress", "Blocked", "Testing", "Completed"];
  const visible = actions.filter(action => !clientId || String(action.client_id) === clientId);
  const inColumn = (action: Action, column: string) => { const status = (action.status || "").toLowerCase(); if (column === "Open") return ["open", "to do", "todo"].includes(status); if (column === "In Progress") return ["in progress", "in-progress", "in progress"].includes(status); if (column === "Completed") return ["done", "completed", "closed"].includes(status); return status === column.toLowerCase(); };
  const move = async (id: number, status: string): Promise<boolean> => {
    const item = actions.find(action => action.id === id); if (!item) return false;
    const response = await apiFetch(`/action-items/${id}`, { method: "PATCH", body: JSON.stringify({ title: item.title, owner: item.owner, due_date: item.due_date || null, priority: item.priority, status, meeting_id: item.meeting_id }) });
    if (!response.ok) { setNotice("Could not update the action item."); return false; }
    const updated = await response.json(); setData(previous => ({ ...previous, actions: previous.actions.map(action => action.id === id ? updated : action) })); setNotice("Action item moved.");
    return true;
  };
  const create = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const payload = { client_id: Number(form.get("client_id")), title: String(form.get("title")), owner: String(form.get("owner")), due_date: form.get("due_date") || null, priority: String(form.get("priority")), status: "Open", tags: String(form.get("tags") || "").split(",").map(tag => tag.trim()).filter(Boolean) }; const response = await apiFetch("/action-items", { method: "POST", body: JSON.stringify(payload) }); if (!response.ok) { setNotice("Could not create the action item."); return; } const created = await response.json(); setData(previous => ({ ...previous, actions: [created, ...previous.actions] })); setShowCreate(false); setNotice("Action item created."); };
  return <section className="mt-6"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Action item engine</p><h2 className="text-2xl font-semibold tracking-tight">Triage and delivery board</h2><p className="mt-1 text-sm text-slate-500">Move commitments through the delivery pipeline and keep ownership visible.</p></div><div className="module-filters"><label>Client<select value={clientId} onChange={event => setClientId(event.target.value)}><option value="">All clients</option>{clients.map(client => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label><button type="button" onClick={() => setShowCreate(true)}>Add action item</button></div></div>{showCreate && <div className="modal-backdrop"><form className="modal-card space-y-4" onSubmit={create}><div className="flex items-center justify-between"><div><p className="eyebrow">New action item</p><h3 className="text-lg font-semibold">Create commitment</h3></div><button type="button" className="clear-filter" onClick={() => setShowCreate(false)}>Close</button></div><label>Client<select name="client_id" value={clientId} onChange={event => setClientId(event.target.value)} required>{clients.map(client => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label><label>Action item<input name="title" required placeholder="Confirm API mapping with client"/></label><div className="grid gap-3 sm:grid-cols-2"><label>Owner<input name="owner" required placeholder="Delivery lead"/></label><label>EDA<input name="due_date" type="date"/></label></div><div className="grid gap-3 sm:grid-cols-2"><label>Priority<select name="priority" defaultValue="Medium"><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select></label><label>Tags<input name="tags" placeholder="api, client-review"/></label></div><button>Create action item</button></form></div>}<div className="kanban-board mt-6">{columns.map(column => <div className="kanban-column" key={column} onDragOver={event => event.preventDefault()} onDrop={event => { const id = Number(event.dataTransfer.getData("text/plain")); if (id) move(id, column); }}><div className="flex items-center justify-between"><h3 className="font-semibold">{column}</h3><span className="soft-pill">{visible.filter(action => inColumn(action, column)).length}</span></div><div className="mt-3 space-y-3">{visible.filter(action => inColumn(action, column)).map(action => <article className="kanban-card" draggable key={action.id} onDragStart={event => event.dataTransfer.setData("text/plain", String(action.id))}><p className="font-medium">{action.title}</p><p className="mt-2 text-xs text-slate-500">{action.owner || "Unassigned"}{action.due_date ? ` · EDA ${action.due_date}` : ""}</p><span className={`priority-dot priority-${(action.priority || "medium").toLowerCase()}`}>{action.priority}</span></article>)}</div></div>)}</div></section>;
}

function DashboardModule({ clients, clientId, setClientId, selectedName, data, actionsByMeeting }: any) { const meetings = data.meetings.filter((meeting: Meeting) => !clientId || String(meeting.client_id) === clientId); const actions = data.actions.filter((action: Action) => !clientId || String(action.client_id) === clientId); const features = data.features.filter((feature: Feature) => !clientId || String(feature.client_id) === clientId); const openActions = actions.filter((action: Action) => action.status !== "Done"); const overdueActions = openActions.filter((action: Action) => new Date(`${action.due_date}T00:00:00`) < new Date()); const averageProgress = features.length ? Math.round(features.reduce((sum: number, feature: Feature) => sum + feature.progress, 0) / features.length) : 0; return <><section className="mt-6 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Executive dashboard</p><h2 className="text-2xl font-semibold tracking-tight">Delivery overview</h2><p className="mt-1 text-sm text-slate-500">A visual snapshot of meetings, commitments and development for {selectedName || "both client accounts"}.</p></div><div className="module-filters"><label>Dashboard client<select value={clientId} onChange={event => setClientId(event.target.value)}><option value="">All clients</option>{clients.map((client: Client) => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label><span className="soft-pill">Live summary</span></div></section><section className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><SummaryCard label="Meetings recorded" value={meetings.length} tone="indigo"/><SummaryCard label="Open actions" value={openActions.length} tone="amber"/><SummaryCard label="Overdue actions" value={overdueActions.length} tone="rose"/><SummaryCard label="Development progress" value={`${averageProgress}%`} tone="emerald"/></section><section className="mt-6 grid gap-6 lg:grid-cols-[1.15fr_.85fr]"><article className="surface-card p-6"><div className="flex items-center justify-between"><div><p className="eyebrow">Meeting intelligence</p><h3 className="mt-1 text-lg font-semibold">Recent meeting records</h3></div><span className="soft-pill">Agenda · Discussion · Actions</span></div><div className="mt-5 space-y-4">{meetings.length ? meetings.slice(0, 4).map((meeting: Meeting) => <div key={meeting.id} className="dashboard-meeting"><div className="dashboard-meeting-date">{new Date(meeting.scheduled_for).toLocaleDateString(undefined, { month: "short", day: "numeric" })}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap justify-between gap-2"><h4 className="font-semibold text-slate-800">{meeting.title}</h4><span className="text-xs text-slate-500">{actionsByMeeting.get(meeting.id)?.length || 0} actions</span></div><p className="mt-1 text-xs font-medium uppercase tracking-wide text-indigo-600">Agenda</p><p className="line-clamp-2 text-sm text-slate-600">{meeting.agenda || "Not recorded"}</p><p className="mt-2 text-xs font-medium uppercase tracking-wide text-slate-500">Discussion</p><p className="line-clamp-2 text-sm text-slate-600">{meeting.notes || "Not recorded"}</p></div></div>) : <Empty icon="◷" title="No meeting data yet" text="Your meeting records will appear here once added."/>}</div></article><article className="surface-card p-6"><div><p className="eyebrow">Action queue</p><h3 className="mt-1 text-lg font-semibold">Items needing attention</h3></div><div className="mt-5 space-y-3">{openActions.length ? openActions.slice(0, 6).map((action: Action) => <div className="dashboard-action" key={action.id}><div><p className="font-medium text-slate-800">{action.title}</p><p className="mt-1 text-xs text-slate-500">{action.owner} · Due {action.due_date}</p></div><span className={`priority-dot priority-${action.priority.toLowerCase()}`}>{action.priority}</span></div>) : <Empty icon="✓" title="No open actions" text="New meeting follow-ups will be surfaced here."/>}</div></article></section><section className="mt-6"><article className="surface-card p-6"><div className="flex items-center justify-between"><div><p className="eyebrow">Development pulse</p><h3 className="mt-1 text-lg font-semibold">Pipeline at a glance</h3></div><span className="soft-pill">{features.length} items</span></div>{features.length ? <div className="mt-5 grid gap-4 md:grid-cols-2">{features.map((feature: Feature) => <div className="dashboard-feature" key={feature.id}><div className="flex justify-between gap-3"><div><p className="font-medium text-slate-800">{feature.name}</p><p className="mt-1 text-xs text-slate-500">{feature.developer} · {feature.sprint} · Due {feature.target_date}</p></div><span className="text-sm font-semibold text-slate-700">{feature.progress}%</span></div><div className="progress-track progress-indigo"><div style={{ width: `${feature.progress}%` }}/></div><p className="mt-2 text-xs text-slate-500">{feature.dependency ? `Dependency: ${feature.dependency}` : "No dependency recorded"}</p></div>)}</div> : <Empty icon="↗" title="No development items yet" text="Your pipeline parameters will appear here once added."/>}</article></section></>; }

function SummaryCard({ label, value, tone }: { label: string; value: string | number; tone: string }) { return <article className={`summary-card summary-${tone}`}><p className="text-sm font-medium text-slate-600">{label}</p><p className="mt-4 text-3xl font-semibold tracking-tight text-slate-900">{value}</p><div className="summary-glow"/></article>; }

// @ts-ignore - the card is wrapped below to add the action manager props.
function MeetingsModule({ clients, clientId, setClientId, selectedName, data, actionsByMeeting, meetingDate, setMeetingDate, submit, updateMeeting, deleteMeeting, updateAction, deleteAction }: any) { const visibleMeetings = data.meetings.filter((meeting: Meeting) => (!clientId || String(meeting.client_id) === clientId) && (!meetingDate || meeting.scheduled_for.slice(0, 10) === meetingDate)); return <><section className="mt-6 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Meeting module</p><h2 className="text-2xl font-semibold tracking-tight">Meeting history</h2><p className="mt-1 text-sm text-slate-500">Revisit every agenda, discussion and commitment for {selectedName || "both client accounts"}.</p></div><div className="module-filters"><label>Client<select value={clientId} onChange={event => setClientId(event.target.value)}><option value="">All clients</option>{clients.map((client: Client) => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label><label className="date-filter">Meeting date<input aria-label="Filter meetings by date" type="date" value={meetingDate} onChange={event => setMeetingDate(event.target.value)}/></label>{(meetingDate || clientId) && <button className="clear-filter" onClick={() => { setMeetingDate(""); setClientId(""); }}>Clear</button>}<span className="soft-pill">{visibleMeetings.length} shown</span></div></section><section className="mt-5 grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><div className="space-y-6"><MeetingForm clients={clients} defaultClient={clientId} submit={submit}/><ActionForm clients={clients} defaultClient={clientId} meetings={data.meetings} submit={submit}/></div><div className="space-y-4">{visibleMeetings.length ? visibleMeetings.map((meeting: Meeting) => <MeetingCard key={meeting.id} meeting={meeting} actions={actionsByMeeting.get(meeting.id) || []} updateMeeting={updateMeeting} deleteMeeting={deleteMeeting} updateAction={updateAction} deleteAction={deleteAction}/>) : <article className="surface-card"><Empty icon="◷" title={meetingDate || clientId ? "No meetings match these filters" : "No meeting history yet"} text={meetingDate || clientId ? "Clear or change the filters to view other meetings." : "Create your first meeting to build a searchable record of discussions and commitments."}/></article>}</div></section></>; }
function DevelopmentModule({ clients, clientId, setClientId, selectedName, features, submit, updateProgress, deleteFeature }: any) { const [sprintFilter, setSprintFilter] = useState(""); const [statusFilter, setStatusFilter] = useState(""); const sprints = Array.from(new Set<string>(features.map((feature: Feature) => feature.sprint))).sort(); const visibleFeatures = features.filter((feature: Feature) => (!clientId || String(feature.client_id) === clientId) && (!sprintFilter || feature.sprint === sprintFilter) && (!statusFilter || (statusFilter === "complete" ? feature.progress === 100 : statusFilter === "active" && feature.progress < 100))); return <><section className="mt-6 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Development module</p><h2 className="text-2xl font-semibold tracking-tight">Development pipeline</h2><p className="mt-1 text-sm text-slate-500">Each item shows its owner, sprint, dependency, due date and live progress for {selectedName || "both client accounts"}.</p></div><div className="module-filters"><label>Client<select value={clientId} onChange={event => setClientId(event.target.value)}><option value="">All clients</option>{clients.map((client: Client) => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label><label>Pipeline / sprint<select value={sprintFilter} onChange={event => setSprintFilter(event.target.value)}><option value="">All sprints</option>{sprints.map((sprint: string) => <option value={sprint} key={sprint}>{sprint}</option>)}</select></label><label>Status<select value={statusFilter} onChange={event => setStatusFilter(event.target.value)}><option value="">All statuses</option><option value="active">Active</option><option value="complete">Complete</option></select></label><span className="soft-pill">{visibleFeatures.length} shown</span></div></section><section className="mt-5 grid gap-6 lg:grid-cols-[.72fr_1.28fr]"><FeatureForm clients={clients} defaultClient={clientId} submit={submit}/><div className="space-y-4">{visibleFeatures.length ? visibleFeatures.map((feature: Feature) => <FeatureCard key={feature.id} feature={feature} updateProgress={updateProgress} deleteFeature={deleteFeature}/>) : <article className="surface-card"><Empty icon="↗" title={features.length ? "No pipeline items match these filters" : "Your pipeline is clear"} text={features.length ? "Clear or change the filters to view other development items." : "Add a development item with a due date to begin tracking delivery."}/></article>}</div></section><p className="mt-5 text-xs text-slate-500"><span className="font-medium text-orange-600">Orange</span> = 2–3 days overdue · <span className="font-medium text-red-600">Red</span> = 4+ days overdue</p></>; }
function MeetingCard({ meeting, actions, updateMeeting, deleteMeeting }: { meeting: Meeting; actions: Action[]; updateMeeting: (id: number, payload: Record<string, string>) => Promise<Meeting | null>; deleteMeeting: (id: number, title: string) => void }) { const date = new Date(meeting.scheduled_for); const editable = meeting.created_at ? Date.now() - Date.parse(meeting.created_at) <= 48 * 60 * 60 * 1000 : false; const [editing, setEditing] = useState(false); const [form, setForm] = useState({ title: meeting.title, scheduled_for: meeting.scheduled_for.slice(0, 16), attendees: meeting.attendees, agenda: meeting.agenda, notes: meeting.notes }); useEffect(() => setForm({ title: meeting.title, scheduled_for: meeting.scheduled_for.slice(0, 16), attendees: meeting.attendees, agenda: meeting.agenda, notes: meeting.notes }), [meeting]); const save = async (event: FormEvent) => { event.preventDefault(); const updated = await updateMeeting(meeting.id, form); if (updated) setEditing(false); }; return <article className="surface-card p-6"><div className="flex gap-4"><div className="meeting-date h-12 w-14 text-sm">{date.toLocaleDateString(undefined, { month: "short", day: "numeric" })}</div><div className="min-w-0 flex-1">{editing ? <form onSubmit={save} className="space-y-3"><div className="flex items-center justify-between gap-3"><input aria-label="Meeting title" value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} required/><button type="button" className="clear-filter" onClick={() => setEditing(false)}>Cancel</button></div><label>Date and time<input type="datetime-local" value={form.scheduled_for} onChange={event => setForm({ ...form, scheduled_for: event.target.value })} required/></label><label>Attendees<textarea value={form.attendees} onChange={event => setForm({ ...form, attendees: event.target.value })}/></label><label>Agenda<textarea value={form.agenda} onChange={event => setForm({ ...form, agenda: event.target.value })}/></label><label>Discussion points<textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })}/></label><button>Save changes</button></form> : <><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="text-lg font-semibold text-slate-900">{meeting.title}</h3><div className="flex items-center gap-2"><span className="text-xs text-slate-500">{date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</span><button type="button" className="edit-button" disabled={!editable} onClick={() => setEditing(true)}>{editable ? "Edit" : "Edit closed"}</button><button type="button" className="delete-button" onClick={() => deleteMeeting(meeting.id, meeting.title)}>Delete</button></div></div><p className="mt-1 text-sm text-slate-500">{meeting.attendees || "Attendees not recorded"}</p><div className="meeting-details"><Detail label="Agenda" value={meeting.agenda}/><Detail label="Discussion points" value={meeting.notes}/><div><p className="detail-label">Action items</p>{actions.length ? <ul className="mt-2 space-y-2">{actions.map(action => <li key={action.id} className="action-line"><span>{action.title}</span><span>{action.owner} · {action.due_date}</span></li>)}</ul> : <p className="mt-1 text-sm text-slate-500">No linked actions.</p>}</div></div></>}</div></div></article>; }
function Detail({ label, value }: { label: string; value: string }) { return <div><p className="detail-label">{label}</p><p className="mt-1 whitespace-pre-line text-sm leading-6 text-slate-700">{value || "Not recorded"}</p></div>; }
function FeatureCard({ feature, updateProgress, deleteFeature }: { feature: Feature; updateProgress: (id: number, progress: number) => void; deleteFeature: (id: number, name: string) => void }) { const [draftProgress, setDraftProgress] = useState(feature.progress); useEffect(() => setDraftProgress(feature.progress), [feature.id, feature.progress]); const today = new Date(); today.setHours(0,0,0,0); const due = new Date(`${feature.target_date}T00:00:00`); const daysLate = feature.progress < 100 ? Math.max(0, Math.floor((today.getTime() - due.getTime()) / 86400000)) : 0; const tone = daysLate >= 4 ? "red" : daysLate >= 2 ? "orange" : "indigo"; const label = daysLate >= 4 ? `${daysLate} days overdue` : daysLate >= 2 ? `${daysLate} days overdue` : feature.progress === 100 ? "Complete" : "On track"; return <article className="surface-card p-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><p className="eyebrow">{feature.sprint}</p><h3 className="mt-1 text-lg font-semibold">{feature.name}</h3><p className="mt-1 text-sm text-slate-500">{feature.developer} · Due {new Date(`${feature.target_date}T00:00:00`).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })}</p></div><span className={`status-pill status-${tone}`}>{label}</span></div>{feature.dependency && <p className="mt-4 rounded-xl bg-slate-50 px-3 py-2 text-sm text-slate-600">Dependency: {feature.dependency}</p>}<div className="mt-5 flex items-center justify-between"><span className="text-sm font-medium text-slate-700">Progress</span><span className="text-sm font-semibold text-slate-900">{feature.progress}%</span></div><div className={`progress-track progress-${tone}`}><div style={{ width: `${feature.progress}%` }}/></div><div className="mt-4 flex flex-col gap-3 sm:flex-row sm:items-center"><input aria-label={`Progress for ${feature.name}`} className="progress-slider" type="range" min="0" max="100" value={draftProgress} onChange={event => setDraftProgress(Number(event.target.value))}/><div className="flex items-center gap-2"><output className="text-sm font-medium text-slate-600">{draftProgress}%</output><button type="button" onClick={() => updateProgress(feature.id, draftProgress)}>Update</button><button type="button" className="delete-button" onClick={() => deleteFeature(feature.id, feature.name)}>Delete</button></div></div></article>; }
function Empty({ icon, title, text }: { icon: string; title: string; text: string }) { return <div className="empty-state m-6"><span>{icon}</span><div><p className="font-medium text-slate-700">{title}</p><p className="mt-1 text-sm leading-6 text-slate-500">{text}</p></div></div>; }
function FormCard({ title, hint, children, onSubmit }: any) { return <form className="surface-card space-y-4 p-6" onSubmit={onSubmit}><div><p className="eyebrow">New record</p><h2 className="mt-1 text-lg font-semibold">{title}</h2><p className="mt-1 text-sm text-slate-500">{hint}</p></div>{children}</form>; }
function Select({ clients, value }: { clients: Client[]; value: string }) { return <label>Client account<select name="client_id" required defaultValue={value}><option value="" disabled>Select Finkomm or HHP</option>{clients.map(client => <option key={client.id} value={client.id}>{client.name}</option>)}</select></label>; }

const OriginalMeetingCard = MeetingCard;
 function DiscussionPoints({ meeting }: { meeting: Meeting }) { const [points, setPoints] = useState<{ id: number; title: string; content: string; status: string; linked_action_item_id: number | null }[]>([]); const [draft, setDraft] = useState(""); const [editing, setEditing] = useState<number | null>(null); const load = () => apiFetch(`/meetings/${meeting.id}/discussion-points`).then(response => response.ok ? response.json() : []).then(setPoints).catch(() => undefined); useEffect(() => { load(); }, [meeting.id]); const add = async (event: FormEvent) => { event.preventDefault(); if (!draft.trim()) return; const response = await apiFetch(`/meetings/${meeting.id}/discussion-points`, { method: "POST", body: JSON.stringify({ title: draft.trim(), content: draft.trim(), status: "Open" }) }); if (response.ok) { setDraft(""); load(); } }; const edit = async (point: { id: number; title: string; content: string; status: string }) => { const title = window.prompt("Edit discussion point", point.title); if (title === null || !title.trim()) return; const response = await apiFetch(`/discussion-points/${point.id}`, { method: "PATCH", body: JSON.stringify({ title: title.trim(), content: point.content, status: point.status }) }); if (response.ok) { setEditing(null); load(); } }; const convert = async (point: { id: number; title: string }) => { const response = await apiFetch(`/discussion-points/${point.id}/convert`, { method: "POST", body: JSON.stringify({ client_id: meeting.client_id, title: point.title, owner: "Discussion owner", due_date: null, priority: "Medium", status: "Open", meeting_id: meeting.id }) }); if (response.ok) load(); }; return <div className="mt-4 rounded-2xl border border-violet-100 bg-violet-50/40 p-4"><div className="flex items-center justify-between"><p className="detail-label">Discussion points</p><span className="soft-pill">{points.length}</span></div><div className="mt-2 space-y-2">{points.map(point => <div className="rounded-xl bg-white p-3" key={point.id}><div className="flex items-start justify-between gap-2"><div><p className="text-sm font-medium">{point.title}</p><p className="mt-1 text-xs text-slate-500">{point.status}</p></div><div className="flex gap-2"><button type="button" className="action-small" onClick={() => edit(point)}>Edit</button>{!point.linked_action_item_id && <button type="button" className="action-small" onClick={() => convert(point)}>Convert to action</button>}</div></div></div>)}</div><form className="mt-3 flex gap-2" onSubmit={add}><input value={draft} onChange={event => setDraft(event.target.value)} placeholder="Add a discussion point" aria-label="Discussion point"/><button type="submit">Add</button></form></div>; }
// @ts-ignore Runtime wrapper adds discussion and action management.
MeetingCard = function MeetingCardWithActionManagement(props: any) { return <><OriginalMeetingCard {...props}/><DiscussionPoints meeting={props.meeting}/><ActionManager actions={props.actions} updateAction={props.updateAction} deleteAction={props.deleteAction}/></>; };

function ActionManager({ actions, updateAction, deleteAction }: { actions: Action[]; updateAction: (id: number, payload: Record<string, string | null>) => Promise<Action | null>; deleteAction: (id: number, title: string) => void }) { const [editingId, setEditingId] = useState<number | null>(null); const [draft, setDraft] = useState<Action | null>(null); if (!actions.length) return null; const begin = (action: Action) => { setEditingId(action.id); setDraft({ ...action }); }; const save = async (event: FormEvent) => { event.preventDefault(); if (!draft) return; const result = await updateAction(draft.id, { title: draft.title, owner: draft.owner, due_date: draft.due_date, priority: draft.priority, status: draft.status, meeting_id: draft.meeting_id ? String(draft.meeting_id) : null }); if (result) { setEditingId(null); setDraft(null); } }; return <div className="action-manager"><div className="action-manager-heading"><span>Manage action items</span><span>{actions.filter(action => action.status === "Done").length}/{actions.length} complete</span></div>{actions.map(action => editingId === action.id && draft ? <form key={action.id} className="action-edit-form" onSubmit={save}><input aria-label="Action title" value={draft.title} onChange={event => setDraft({ ...draft, title: event.target.value })} required/><div className="grid gap-2 sm:grid-cols-2"><input aria-label="Action owner" value={draft.owner} onChange={event => setDraft({ ...draft, owner: event.target.value })} required/><input aria-label="Action due date" type="date" value={draft.due_date} onChange={event => setDraft({ ...draft, due_date: event.target.value })} required/></div><div className="flex flex-wrap gap-2"><select aria-label="Action priority" value={draft.priority} onChange={event => setDraft({ ...draft, priority: event.target.value })}><option>High</option><option>Medium</option><option>Low</option></select><select aria-label="Action status" value={draft.status} onChange={event => setDraft({ ...draft, status: event.target.value })}><option>To do</option><option>In progress</option><option>Done</option></select><button>Save</button><button type="button" className="clear-filter" onClick={() => { setEditingId(null); setDraft(null); }}>Cancel</button></div></form> : <div className={`managed-action ${action.status === "Done" ? "managed-action-done" : ""}`} key={action.id}><div><p className="font-medium">{action.title}</p><p className="text-xs text-slate-500">{action.owner} · Due {action.due_date} · {action.priority}</p></div><div className="flex shrink-0 gap-2"><button type="button" className="action-small" onClick={() => updateAction(action.id, { title: action.title, owner: action.owner, due_date: action.due_date, priority: action.priority, status: action.status === "Done" ? "In progress" : "Done", meeting_id: action.meeting_id ? String(action.meeting_id) : null })}>{action.status === "Done" ? "Reopen" : "Mark done"}</button><button type="button" className="action-small" onClick={() => begin(action)}>Edit</button><button type="button" className="action-small action-delete" onClick={() => deleteAction(action.id, action.title)}>Delete</button></div></div>)}</div>; }

const OriginalDashboardModule = DashboardModule;
// @ts-expect-error Function declarations are mutable at runtime; the dashboard is replaced with the tile view.
DashboardModule = function DashboardTileView(props: any) { const { clients, clientId, setClientId, selectedName, data, actionsByMeeting, meetingId, setMeetingId, meetingDate, setMeetingDate } = props; const meetings = data.meetings.filter((meeting: Meeting) => (!clientId || String(meeting.client_id) === clientId) && (!meetingId || String(meeting.id) === meetingId) && (!meetingDate || meeting.scheduled_for.slice(0, 10) === meetingDate)); const actions = data.actions.filter((action: Action) => !clientId || String(action.client_id) === clientId); const features = data.features.filter((feature: Feature) => !clientId || String(feature.client_id) === clientId); return <><section className="mt-6 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Executive dashboard</p><h2 className="text-2xl font-semibold tracking-tight">Delivery overview</h2><p className="mt-1 text-sm text-slate-500">Visual meeting and development summary for {selectedName || "both client accounts"}.</p></div><div className="module-filters"><label>Client<select value={clientId} onChange={event => setClientId(event.target.value)}><option value="">All clients</option>{clients.map((client: Client) => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label><label>Meeting<select value={meetingId} onChange={event => setMeetingId(event.target.value)}><option value="">All meetings</option>{data.meetings.filter((meeting: Meeting) => !clientId || String(meeting.client_id) === clientId).map((meeting: Meeting) => <option value={meeting.id} key={meeting.id}>{meeting.title}</option>)}</select></label><label className="date-filter">Date<input type="date" value={meetingDate} onChange={event => setMeetingDate(event.target.value)}/></label>{(clientId || meetingId || meetingDate) && <button className="clear-filter" onClick={() => { setClientId(""); setMeetingId(""); setMeetingDate(""); }}>Clear</button>}</div></section><section className="mt-5 grid gap-4 sm:grid-cols-3"><SummaryCard label="Meetings shown" value={meetings.length} tone="indigo"/><SummaryCard label="Open actions" value={actions.filter((action: Action) => action.status !== "Done").length} tone="amber"/><SummaryCard label="Development items" value={features.length} tone="emerald"/></section><section className="mt-6 space-y-5">{meetings.length ? meetings.map((meeting: Meeting) => <article className="surface-card p-6" key={meeting.id}><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="eyebrow">Meeting · {new Date(meeting.scheduled_for).toLocaleDateString()}</p><h3 className="mt-1 text-xl font-semibold">{meeting.title}</h3></div><span className="soft-pill">{actionsByMeeting.get(meeting.id)?.length || 0} action items</span></div><div className="dashboard-tiles mt-5"><div className="dashboard-tile dashboard-tile-agenda"><p className="tile-label">Agenda</p><p>{meeting.agenda || "Not recorded"}</p></div><div className="dashboard-tile dashboard-tile-discussion"><p className="tile-label">Discussion points</p><p>{meeting.notes || "Not recorded"}</p></div><div className="dashboard-tile dashboard-tile-actions"><p className="tile-label">Action items</p>{actionsByMeeting.get(meeting.id)?.length ? <ul>{actionsByMeeting.get(meeting.id).map((action: Action) => <li key={action.id}>{action.title}<span>{action.owner} · {action.status}</span></li>)}</ul> : <p>No linked actions.</p>}</div></div></article>) : <article className="surface-card"><Empty icon="◷" title="No meetings match these filters" text="Clear the filters or add a meeting to see agenda, discussion and actions here."/></article>}</section><section className="mt-6"><article className="surface-card p-6"><div className="flex items-center justify-between"><div><p className="eyebrow">Development pulse</p><h3 className="mt-1 text-lg font-semibold">Pipeline visual</h3></div><span className="soft-pill">{features.length} items</span></div>{features.length ? <div className="mt-5 grid gap-4 md:grid-cols-2">{features.map((feature: Feature) => <div className="dashboard-feature" key={feature.id}><div className="flex justify-between gap-3"><div><p className="font-medium text-slate-800">{feature.name}</p><p className="mt-1 text-xs text-slate-500">{feature.developer} · {feature.sprint} · Due {feature.target_date}</p></div><span className="text-sm font-semibold text-slate-700">{feature.progress}%</span></div><div className="progress-track progress-indigo"><div style={{ width: `${feature.progress}%` }}/></div><p className="mt-2 text-xs text-slate-500">{feature.dependency ? `Dependency: ${feature.dependency}` : "No dependency recorded"}</p></div>)}</div> : <Empty icon="↗" title="No development items yet" text="Your development items will appear here once added."/>}</article></section></>; };
function MeetingForm({ clients, defaultClient, submit }: any) { return <FormCard title="Record a meeting" hint="Create a complete history you can return to later." onSubmit={(event: FormEvent<HTMLFormElement>) => submit(event, "/meetings")}><Select clients={clients} value={defaultClient}/><label>Meeting title<input name="title" required placeholder="Weekly delivery review"/></label><label>Date and time<input name="scheduled_for" required type="datetime-local"/></label><label>Attendees<textarea name="attendees" placeholder="Names or teams who attended"/></label><label>Agenda<textarea name="agenda" placeholder="Topics planned for the meeting"/></label><label>Discussion points<textarea name="notes" placeholder="What was discussed, decided or deferred"/></label><button>Save meeting</button></FormCard>; }
function ActionForm({ clients, defaultClient, meetings, submit }: any) { return <FormCard title="Link an action item" hint="Associate a follow-up with a recorded meeting." onSubmit={(event: FormEvent<HTMLFormElement>) => submit(event, "/actions")}><Select clients={clients} value={defaultClient}/><label>Meeting<select name="meeting_id" defaultValue=""><option value="">Not linked to a meeting</option>{meetings.map((meeting: Meeting) => <option key={meeting.id} value={meeting.id}>{meeting.title} · {new Date(meeting.scheduled_for).toLocaleDateString()}</option>)}</select></label><label>Action item<input name="title" required placeholder="Share updated screens"/></label><div className="grid gap-4 sm:grid-cols-2"><label>Owner<input name="owner" required placeholder="Design team"/></label><label>Due date<input name="due_date" required type="date"/></label></div><label>Priority<select name="priority" defaultValue="Medium"><option>High</option><option>Medium</option><option>Low</option></select></label><button>Add action item</button></FormCard>; }
function FeatureForm({ clients, defaultClient, submit }: any) { return <FormCard title="Add development item" hint="Set its timeline and assign responsibility." onSubmit={(event: FormEvent<HTMLFormElement>) => submit(event, "/features")}><Select clients={clients} value={defaultClient}/><label>Development item<input name="name" required placeholder="Fleet health summary"/></label><div className="grid gap-4 sm:grid-cols-2"><label>Developer<input name="developer" required placeholder="Developer 1"/></label><label>Pipeline / sprint<input name="sprint" required placeholder="Sprint 8"/></label></div><div className="grid gap-4 sm:grid-cols-2"><label>Current progress (%)<input name="progress" type="number" min="0" max="100" defaultValue="0" required/></label><label>Due date<input name="target_date" type="date" required/></label></div><label>Dependency<input name="dependency" placeholder="Client sign-off (optional)"/></label><button>Add to pipeline</button></FormCard>; }

function RequirementsModule({ clients, clientId, setClientId, selectedName, requirements, submit, setData }: any) { const [statusFilter, setStatusFilter] = useState(""); const [editing, setEditing] = useState<Requirement | null>(null); const visible = requirements.filter((requirement: Requirement) => (!clientId || String(requirement.client_id) === clientId) && (!statusFilter || requirement.status === statusFilter)); const update = async (requirement: Requirement) => { const response = await fetch(`${api}/requirements/${requirement.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(requirement) }); if (!response.ok) return; const updated = await response.json(); setData((previous: Dashboard) => ({ ...previous, requirements: previous.requirements.map(item => item.id === updated.id ? updated : item) })); setEditing(null); }; const remove = async (requirement: Requirement) => { if (!window.confirm(`Delete requirement “${requirement.title}”?`)) return; const response = await fetch(`${api}/requirements/${requirement.id}`, { method: "DELETE" }); if (response.ok) setData((previous: Dashboard) => ({ ...previous, requirements: previous.requirements.filter(item => item.id !== requirement.id) })); }; return <><section className="mt-6 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Requirements module</p><h2 className="text-2xl font-semibold tracking-tight">Requirement gathering workspace</h2><p className="mt-1 text-sm text-slate-500">Capture, clarify and move requirements through review for {selectedName || "both client accounts"}.</p></div><div className="module-filters"><label>Client<select value={clientId} onChange={event => setClientId(event.target.value)}><option value="">All clients</option>{clients.map((client: Client) => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label><label>Status<select value={statusFilter} onChange={event => setStatusFilter(event.target.value)}><option value="">All statuses</option><option>Draft</option><option>Under review</option><option>Approved</option><option>Rejected</option><option>Implemented</option></select></label><span className="soft-pill">{visible.length} shown</span></div></section><section className="mt-5 grid gap-6 lg:grid-cols-[.75fr_1.25fr]"><RequirementForm clients={clients} defaultClient={clientId} submit={submit}/><div className="space-y-4">{visible.length ? visible.map((requirement: Requirement) => editing?.id === requirement.id ? <RequirementEditor key={requirement.id} requirement={editing} setRequirement={setEditing} save={update} cancel={() => setEditing(null)}/> : <RequirementCard key={requirement.id} requirement={requirement} edit={() => setEditing(requirement)} remove={() => remove(requirement)}/>) : <article className="surface-card"><Empty icon="?" title="No requirements yet" text="Capture your first stakeholder need to begin the requirements workflow."/></article>}</div></section></>; }

function RequirementForm({ clients, defaultClient, submit }: any) { return <FormCard title="Capture a requirement" hint="Document the need before it gets lost between meetings." onSubmit={(event: FormEvent<HTMLFormElement>) => submit(event, "/requirements")}><Select clients={clients} value={defaultClient}/><label>Requirement title<input name="title" required placeholder="Learner can download completion certificate"/></label><div className="grid gap-4 sm:grid-cols-2"><label>Source / stakeholder<input name="source" placeholder="Client workshop · Product owner"/></label><label>Owner<input name="owner" placeholder="Business analyst"/></label></div><div className="grid gap-4 sm:grid-cols-2"><label>Type<select name="requirement_type"><option>Functional</option><option>Non-functional</option><option>Reporting</option><option>Integration</option><option>Compliance</option></select></label><label>Priority<select name="priority"><option>High</option><option>Medium</option><option>Low</option></select></label></div><label>Business objective<textarea name="business_objective" placeholder="What business outcome should this support?"/></label><label>Requirement description<textarea name="description" required placeholder="Describe the user need, context and expected behaviour."/></label><label>Acceptance criteria<textarea name="acceptance_criteria" placeholder="Given / When / Then or testable completion conditions"/></label><div className="grid gap-4 sm:grid-cols-2"><label>Status<select name="status"><option>Draft</option><option>Under review</option><option>Approved</option><option>Rejected</option><option>Implemented</option></select></label><label>Target date<input name="target_date" type="date"/></label></div><label>Dependencies<textarea name="dependencies" placeholder="Other features, decisions, data or approvals"/></label><label>Notes<textarea name="notes" placeholder="Open questions and follow-ups"/></label><button>Save requirement</button></FormCard>; }

function RequirementCard({ requirement, edit, remove }: { requirement: Requirement; edit: () => void; remove: () => void }) { return <article className="surface-card p-6"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex flex-wrap gap-2"><span className="status-pill status-indigo">{requirement.status}</span><span className="soft-pill">{requirement.requirement_type}</span><span className={`priority-dot priority-${requirement.priority.toLowerCase()}`}>{requirement.priority}</span></div><h3 className="mt-3 text-lg font-semibold">{requirement.title}</h3><p className="mt-1 text-sm text-slate-500">Source: {requirement.source || "Not recorded"} · Owner: {requirement.owner || "Unassigned"}{requirement.target_date ? ` · Target ${requirement.target_date}` : ""}</p></div><div className="flex gap-2"><button type="button" className="edit-button" onClick={edit}>Edit</button><button type="button" className="delete-button" onClick={remove}>Delete</button></div></div><div className="requirement-grid mt-5"><Detail label="Business objective" value={requirement.business_objective}/><Detail label="Description" value={requirement.description}/><Detail label="Acceptance criteria" value={requirement.acceptance_criteria}/><Detail label="Dependencies" value={requirement.dependencies}/><Detail label="Notes" value={requirement.notes}/></div></article>; }

function RequirementEditor({ requirement, setRequirement, save, cancel }: any) { return <form className="surface-card space-y-4 p-6" onSubmit={(event: FormEvent) => { event.preventDefault(); save(requirement); }}><div className="flex items-center justify-between"><div><p className="eyebrow">Edit requirement</p><h3 className="mt-1 text-lg font-semibold">Requirement details</h3></div><button type="button" className="clear-filter" onClick={cancel}>Cancel</button></div><label>Title<input value={requirement.title} onChange={event => setRequirement({ ...requirement, title: event.target.value })} required/></label><div className="grid gap-4 sm:grid-cols-2"><label>Source<input value={requirement.source} onChange={event => setRequirement({ ...requirement, source: event.target.value })}/></label><label>Owner<input value={requirement.owner} onChange={event => setRequirement({ ...requirement, owner: event.target.value })}/></label></div><div className="grid gap-4 sm:grid-cols-2"><label>Type<select value={requirement.requirement_type} onChange={event => setRequirement({ ...requirement, requirement_type: event.target.value })}><option>Functional</option><option>Non-functional</option><option>Reporting</option><option>Integration</option><option>Compliance</option></select></label><label>Priority<select value={requirement.priority} onChange={event => setRequirement({ ...requirement, priority: event.target.value })}><option>High</option><option>Medium</option><option>Low</option></select></label></div><label>Business objective<textarea value={requirement.business_objective} onChange={event => setRequirement({ ...requirement, business_objective: event.target.value })}/></label><label>Description<textarea value={requirement.description} onChange={event => setRequirement({ ...requirement, description: event.target.value })} required/></label><label>Acceptance criteria<textarea value={requirement.acceptance_criteria} onChange={event => setRequirement({ ...requirement, acceptance_criteria: event.target.value })}/></label><div className="grid gap-4 sm:grid-cols-2"><label>Status<select value={requirement.status} onChange={event => setRequirement({ ...requirement, status: event.target.value })}><option>Draft</option><option>Under review</option><option>Approved</option><option>Rejected</option><option>Implemented</option></select></label><label>Target date<input type="date" value={requirement.target_date || ""} onChange={event => setRequirement({ ...requirement, target_date: event.target.value || null })}/></label></div><label>Dependencies<textarea value={requirement.dependencies} onChange={event => setRequirement({ ...requirement, dependencies: event.target.value })}/></label><label>Notes<textarea value={requirement.notes} onChange={event => setRequirement({ ...requirement, notes: event.target.value })}/></label><button>Save changes</button></form>; }

function MeetingVaultPanel({ meetings }: { meetings: Meeting[] }) { const [search, setSearch] = useState(""); const [status, setStatus] = useState("all"); const [selected, setSelected] = useState<Meeting | null>(null); const now = Date.now(); const visible = meetings.filter(meeting => (!search || `${meeting.title} ${meeting.agenda} ${meeting.notes}`.toLowerCase().includes(search.toLowerCase())) && (status === "all" || (status === "upcoming" ? Date.parse(meeting.scheduled_for) > now : Date.parse(meeting.scheduled_for) <= now))); return <section className="surface-card mt-6 p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Meeting vault</p><h2 className="text-2xl font-semibold tracking-tight">Searchable meeting history</h2><p className="mt-1 text-sm text-slate-500">Open any meeting to review minutes and discussion-to-action follow-ups.</p></div><div className="module-filters"><label>Search<input value={search} onChange={event => setSearch(event.target.value)} placeholder="Search meetings"/></label><label>Status<select value={status} onChange={event => setStatus(event.target.value)}><option value="all">All</option><option value="upcoming">Upcoming</option><option value="completed">Completed</option></select></label><span className="soft-pill">{visible.length} meetings</span></div></div><div className="mt-4 grid gap-3 md:grid-cols-2 lg:grid-cols-3">{visible.map(meeting => <button type="button" key={meeting.id} className="meeting-vault-card text-left" onClick={() => setSelected(meeting)}><div className="flex items-start justify-between gap-2"><h3 className="font-semibold text-slate-900">{meeting.title}</h3><span className={`status-pill ${Date.parse(meeting.scheduled_for) > now ? "status-emerald" : "status-indigo"}`}>{Date.parse(meeting.scheduled_for) > now ? "Upcoming" : "Completed"}</span></div><p className="mt-2 text-xs text-slate-500">{new Date(meeting.scheduled_for).toLocaleString()}</p><p className="mt-2 line-clamp-2 text-sm text-slate-600">{meeting.agenda || "No agenda recorded"}</p></button>)}</div>{!visible.length && <p className="mt-5 text-sm text-slate-500">No meetings match the current filters.</p>}{selected && <div className="drawer-backdrop" onClick={() => setSelected(null)}><aside className="meeting-drawer" onClick={event => event.stopPropagation()}><div className="flex items-start justify-between gap-4 border-b border-slate-200 pb-4"><div><p className="eyebrow">Meeting detail</p><h3 className="mt-1 text-xl font-semibold">{selected.title}</h3><p className="mt-1 text-sm text-slate-500">{new Date(selected.scheduled_for).toLocaleString()}</p></div><button type="button" className="clear-filter" onClick={() => setSelected(null)}>Close</button></div><div className="mt-5 space-y-5"><Detail label="Attendees" value={selected.attendees}/><Detail label="Agenda" value={selected.agenda}/><Detail label="Discussion notes" value={selected.notes}/><Detail label="Minutes of meeting" value={selected.mom || ""}/><DiscussionPoints meeting={selected}/></div></aside></div>}</section>; }

const OriginalMeetingsModule = MeetingsModule;
// @ts-ignore Runtime wrapper adds the searchable meeting vault and detail drawer.
MeetingsModule = function MeetingVaultModule(props: any) { return <><MeetingVaultPanel meetings={props.data.meetings}/><OriginalMeetingsModule {...props}/></>; };

function DateHighlights({ meetings, selectedDate, setSelectedDate, clientSelected }: { meetings: Meeting[]; selectedDate: string; setSelectedDate: (date: string) => void; clientSelected: boolean }) { const dates = Array.from(new Set(meetings.map(meeting => meeting.scheduled_for.slice(0, 10)))).sort(); return <section className="mt-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Meeting dates</p><p className="text-sm text-slate-500">{clientSelected ? "Highlighted dates show when this client had meetings." : "Select a client to highlight its meeting dates."}</p></div>{selectedDate && <button className="clear-filter" onClick={() => setSelectedDate("")}>Clear date</button>}</div><div className="date-highlight-strip mt-3">{dates.length && clientSelected ? dates.map(date => <button type="button" key={date} className={`date-highlight ${selectedDate === date ? "date-highlight-active" : ""}`} onClick={() => setSelectedDate(date)}><span>{new Date(`${date}T00:00:00`).toLocaleDateString(undefined, { weekday: "short" })}</span><strong>{new Date(`${date}T00:00:00`).getDate()}</strong><small>{new Date(`${date}T00:00:00`).toLocaleDateString(undefined, { month: "short" })}</small></button>) : <span className="text-sm text-slate-500">No highlighted dates available.</span>}</div></section>; }

const OriginalDateHighlights = DateHighlights;
// @ts-expect-error Function declarations are mutable at runtime; replace the separate strip with an inline calendar.
DateHighlights = function InlineMeetingDateFilter({ meetings, selectedDate, setSelectedDate, clientSelected }: { meetings: Meeting[]; selectedDate: string; setSelectedDate: (date: string) => void; clientSelected: boolean }) { const initialMonth = selectedDate ? new Date(`${selectedDate}T00:00:00`) : new Date(); const [month, setMonth] = useState(new Date(initialMonth.getFullYear(), initialMonth.getMonth(), 1)); const meetingDates = new Set(meetings.map(meeting => meeting.scheduled_for.slice(0, 10))); const start = new Date(month.getFullYear(), month.getMonth(), 1); const daysInMonth = new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate(); const leading = start.getDay(); const cells = Array.from({ length: leading + daysInMonth }, (_, index) => index < leading ? null : new Date(month.getFullYear(), month.getMonth(), index - leading + 1)); return <section className="dashboard-date-picker mt-5"><div className="inline-date-header"><div><p className="eyebrow">Meeting date filter</p><p className="text-sm text-slate-500">{clientSelected ? "Dates with meetings are highlighted." : "Select a client to see meeting dates highlighted."}</p></div>{selectedDate && <button className="clear-filter" onClick={() => setSelectedDate("")}>Clear date</button>}</div><div className="inline-calendar"><div className="calendar-toolbar"><button type="button" className="calendar-nav" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() - 1, 1))}>‹</button><strong>{month.toLocaleDateString(undefined, { month: "long", year: "numeric" })}</strong><button type="button" className="calendar-nav" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() + 1, 1))}>›</button></div><div className="calendar-weekdays">{["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map(day => <span key={day}>{day}</span>)}</div><div className="calendar-grid">{cells.map((day, index) => { if (!day) return <span key={`empty-${index}`}/>; const value = `${day.getFullYear()}-${String(day.getMonth() + 1).padStart(2, "0")}-${String(day.getDate()).padStart(2, "0")}`; const hasMeeting = clientSelected && meetingDates.has(value); return <button type="button" key={value} className={`calendar-day ${hasMeeting ? "calendar-day-meeting" : ""} ${selectedDate === value ? "calendar-day-selected" : ""}`} onClick={() => hasMeeting && setSelectedDate(value)} disabled={!hasMeeting}>{day.getDate()}</button>; })}</div></div></section>; };
// Dashboard rendering override: date filtering narrows the meeting selector, and each meeting detail is a separate tile.
// @ts-expect-error Runtime wrapper replaces the presentation component.
DashboardModule = function DashboardTileViewV2(props: any) {
  const { clients, clientId, setClientId, selectedName, data, personal, actionsByMeeting, meetingId, setMeetingId, meetingDate, setMeetingDate } = props;
  const clientMeetings = data.meetings.filter((meeting: Meeting) => !clientId || String(meeting.client_id) === clientId);
  const dateMeetings = clientMeetings.filter((meeting: Meeting) => !meetingDate || meeting.scheduled_for.slice(0, 10) === meetingDate);
  const meetings = dateMeetings.filter((meeting: Meeting) => !meetingId || String(meeting.id) === meetingId);
  const actions = data.actions.filter((action: Action) => !clientId || String(action.client_id) === clientId);
  const features = data.features.filter((feature: Feature) => !clientId || String(feature.client_id) === clientId);
  return <>
    {personal && <section className="mt-6"><div className="mb-3 flex items-center justify-between"><div><p className="eyebrow">Personal delivery insights</p><p className="text-sm text-slate-500">Live metrics from your organization-scoped action register.</p></div><span className="soft-pill">{personal.summary.total_change >= 0 ? "+" : ""}{personal.summary.total_change}% vs previous 2 weeks</span></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><SummaryCard label="Total actions" value={personal.summary.total_action_items} tone="indigo"/><SummaryCard label="On track" value={personal.summary.on_track} tone="emerald"/><SummaryCard label="At risk" value={personal.summary.at_risk} tone="amber"/><SummaryCard label="Overdue" value={personal.summary.overdue} tone="rose"/><SummaryCard label="Completed" value={personal.summary.completed} tone="violet"/></div><div className="mt-4 grid gap-4 lg:grid-cols-2"><article className="surface-card p-5"><p className="eyebrow">Module workload</p><div className="mt-3 space-y-3">{personal.module_breakdown.length ? personal.module_breakdown.map((item: { name: string; count: number }) => <div key={item.name}><div className="flex justify-between text-sm"><span>{item.name}</span><strong>{item.count}</strong></div><div className="progress-track progress-indigo mt-1"><div style={{ width: `${Math.min(100, item.count / Math.max(1, personal.summary.total_action_items) * 100)}%` }}/></div></div>) : <p className="mt-3 text-sm text-slate-500">No action items in your workspace yet.</p>}</div></article><article className="surface-card p-5"><p className="eyebrow">Upcoming deadlines</p><div className="mt-3 space-y-2">{personal.upcoming_deadlines.length ? personal.upcoming_deadlines.slice(0, 5).map((item: { title: string; module: string; eda: string }) => <div key={`${item.title}-${item.eda}`} className="dashboard-action"><div><p className="font-medium">{item.title}</p><p className="text-xs text-slate-500">{item.module} · EDA {item.eda}</p></div></div>) : <p className="mt-3 text-sm text-slate-500">No deadlines in the next 7 days.</p>}</div></article></div></section>}
    <DateHighlights meetings={clientMeetings} selectedDate={meetingDate} setSelectedDate={(date: string) => { setMeetingDate(date); setMeetingId(""); }} clientSelected={Boolean(clientId)} />
    <section className="mt-6 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Executive dashboard</p><h2 className="text-2xl font-semibold tracking-tight">Delivery overview</h2><p className="mt-1 text-sm text-slate-500">Separate visual tiles for {selectedName || "both client accounts"}.</p></div><div className="module-filters"><label>Client<select value={clientId} onChange={event => { setClientId(event.target.value); setMeetingId(""); }}><option value="">All clients</option>{clients.map((client: Client) => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label><label>Meeting<select value={meetingId} onChange={event => setMeetingId(event.target.value)}><option value="">All meetings</option>{dateMeetings.map((meeting: Meeting) => <option value={meeting.id} key={meeting.id}>{meeting.title}</option>)}</select></label><label className="date-filter">Date<input type="date" value={meetingDate} onChange={event => { setMeetingDate(event.target.value); setMeetingId(""); }}/></label>{(clientId || meetingId || meetingDate) && <button className="clear-filter" onClick={() => { setClientId(""); setMeetingId(""); setMeetingDate(""); }}>Clear</button>}</div></section>
    <section className="mt-5 grid gap-4 sm:grid-cols-3"><SummaryCard label="Meetings shown" value={meetings.length} tone="indigo"/><SummaryCard label="Open actions" value={actions.filter((action: Action) => action.status !== "Done").length} tone="amber"/><SummaryCard label="Development items" value={features.length} tone="emerald"/></section>
    <section className="mt-6 space-y-5">{meetings.length ? meetings.map((meeting: Meeting) => <div key={meeting.id}><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><div><p className="eyebrow">Meeting · {new Date(meeting.scheduled_for).toLocaleDateString()}</p><h3 className="text-xl font-semibold">{meeting.title}</h3></div><span className="soft-pill">{actionsByMeeting.get(meeting.id)?.length || 0} action items</span></div><div className="dashboard-tiles"><article className="dashboard-tile dashboard-tile-agenda"><p className="tile-label">Agenda</p><p>{meeting.agenda || "Not recorded"}</p></article><article className="dashboard-tile dashboard-tile-discussion"><p className="tile-label">Discussion points</p><p>{meeting.notes || "Not recorded"}</p></article><article className="dashboard-tile dashboard-tile-actions"><p className="tile-label">Action items</p>{actionsByMeeting.get(meeting.id)?.length ? <ul>{actionsByMeeting.get(meeting.id).map((action: Action) => <li key={action.id}>{action.title}<span>{action.owner} · {action.status}</span></li>)}</ul> : <p>No linked actions.</p>}</article></div></div>) : <article className="surface-card"><Empty icon="◷" title="No meetings match these filters" text="Choose a date first, then select one of the meetings held on that date."/></article>}</section>
    <section className="mt-6"><article className="surface-card p-6"><div className="flex items-center justify-between"><div><p className="eyebrow">Development pulse</p><h3 className="mt-1 text-lg font-semibold">Pipeline visual</h3></div><span className="soft-pill">{features.length} items</span></div>{features.length ? <div className="mt-5 grid gap-4 md:grid-cols-2">{features.map((feature: Feature) => <div className="dashboard-feature" key={feature.id}><div className="flex justify-between gap-3"><div><p className="font-medium text-slate-800">{feature.name}</p><p className="mt-1 text-xs text-slate-500">{feature.developer} · {feature.sprint} · Due {feature.target_date}</p></div><span className="text-sm font-semibold text-slate-700">{feature.progress}%</span></div><div className="progress-track progress-indigo"><div style={{ width: `${feature.progress}%` }}/></div><p className="mt-2 text-xs text-slate-500">{feature.dependency ? `Dependency: ${feature.dependency}` : "No dependency recorded"}</p></div>)}</div> : <Empty icon="↗" title="No development items yet" text="Your development items will appear here once added."/>}</article></section>
  </>;
};

function VisualDashboardModule({ clients, clientId, setClientId, selectedName, data, setMeetingDate }: any) { const [month, setMonth] = useState(() => new Date(new Date().getFullYear(), new Date().getMonth(), 1)); const [selectedDate, setSelectedDate] = useState(""); const meetings = data.meetings.filter((meeting: Meeting) => !clientId || String(meeting.client_id) === clientId); const actions = data.actions.filter((action: Action) => !clientId || String(action.client_id) === clientId); const features = data.features.filter((feature: Feature) => !clientId || String(feature.client_id) === clientId); const dateKey = (day: Date) => `${day.getFullYear()}-${String(day.getMonth() + 1).padStart(2, "0")}-${String(day.getDate()).padStart(2, "0")}`; const meetingCount = new Map<string, number>(); meetings.forEach((meeting: Meeting) => { const key = meeting.scheduled_for.slice(0, 10); meetingCount.set(key, (meetingCount.get(key) || 0) + 1); }); const days = new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate(); const leading = new Date(month.getFullYear(), month.getMonth(), 1).getDay(); const cells = Array.from({ length: leading + days }, (_, index) => index < leading ? null : new Date(month.getFullYear(), month.getMonth(), index - leading + 1)); const selectedMeetings = meetings.filter((meeting: Meeting) => meeting.scheduled_for.slice(0, 10) === selectedDate); const open = actions.filter((action: Action) => !["done", "completed", "closed"].includes((action.status || "").toLowerCase())); const overdue = open.filter((action: Action) => action.due_date && action.due_date < new Date().toISOString().slice(0, 10)); const avgProgress = features.length ? Math.round(features.reduce((total: number, feature: Feature) => total + feature.progress, 0) / features.length) : 0; const chooseDate = (value: string) => { setSelectedDate(value); setMeetingDate(value); }; return <section className="mt-6"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Delivery command centre</p><h2 className="text-3xl font-semibold tracking-tight">{selectedName || "Portfolio overview"}</h2><p className="mt-1 text-sm text-slate-500">Calendar-led view of meetings, commitments, and delivery progress.</p></div><label className="module-filters">Client<select value={clientId} onChange={event => { setClientId(event.target.value); setSelectedDate(""); }}><option value="">All clients</option>{clients.map((client: Client) => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label></div><div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><SummaryCard label="Meetings" value={meetings.length} tone="indigo"/><SummaryCard label="Open actions" value={open.length} tone="amber"/><SummaryCard label="Overdue" value={overdue.length} tone="rose"/><SummaryCard label="Development" value={`${avgProgress}%`} tone="emerald"/></div><div className="mt-6 grid gap-5 lg:grid-cols-[1.25fr_.75fr]"><article className="surface-card calendar-focus p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Schedule</p><h3 className="text-xl font-semibold">{month.toLocaleDateString(undefined, { month: "long", year: "numeric" })}</h3></div><div className="flex gap-2"><button type="button" className="calendar-nav" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() - 1, 1))}>‹</button><button type="button" className="calendar-nav" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() + 1, 1))}>›</button></div></div><div className="calendar-weekdays mt-5">{["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map(day => <span key={day}>{day}</span>)}</div><div className="visual-calendar-grid">{cells.map((day, index) => day ? <button type="button" key={dateKey(day)} onClick={() => meetingCount.has(dateKey(day)) && chooseDate(dateKey(day))} className={`visual-calendar-day ${meetingCount.has(dateKey(day)) ? "has-meeting" : ""} ${selectedDate === dateKey(day) ? "is-selected" : ""}`}><strong>{day.getDate()}</strong>{meetingCount.has(dateKey(day)) && <span>{meetingCount.get(dateKey(day))} meeting{meetingCount.get(dateKey(day)) === 1 ? "" : "s"}</span>}</button> : <span key={`blank-${index}`}/>)}</div><div className="mt-4 flex flex-wrap gap-3 text-xs text-slate-500"><span><i className="calendar-dot calendar-dot-meeting"/> Meeting date</span><span><i className="calendar-dot calendar-dot-selected"/> Selected</span>{selectedDate && <button type="button" className="clear-filter" onClick={() => chooseDate("")}>Clear date</button>}</div></article><article className="surface-card p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Selected day</p><h3 className="text-xl font-semibold">{selectedDate ? new Date(`${selectedDate}T00:00:00`).toLocaleDateString(undefined, { weekday: "long", month: "short", day: "numeric" }) : "Choose a date"}</h3></div><span className="soft-pill">{selectedMeetings.length}</span></div>{selectedMeetings.length ? <div className="mt-4 space-y-3">{selectedMeetings.map((meeting: Meeting) => <div className="calendar-meeting-card" key={meeting.id}><div className="flex justify-between gap-2"><p className="font-semibold">{meeting.title}</p><span className="text-xs text-slate-500">{new Date(meeting.scheduled_for).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</span></div><p className="mt-1 line-clamp-2 text-sm text-slate-500">{meeting.agenda || "No agenda recorded"}</p></div>)}</div> : <div className="calendar-empty mt-5"><span className="text-2xl">◷</span><p>{selectedDate ? "No meetings on this date." : "Dates with meetings are highlighted on the calendar."}</p></div>}</article></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><article className="surface-card p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Action pulse</p><h3 className="text-lg font-semibold">Next commitments</h3></div><span className="soft-pill">{open.length} open</span></div><div className="mt-4 space-y-2">{open.slice(0, 5).map((action: Action) => <div className="dashboard-action" key={action.id}><div><p className="font-medium">{action.title}</p><p className="text-xs text-slate-500">{action.owner || "Unassigned"}</p></div><span className={`priority-dot priority-${(action.priority || "medium").toLowerCase()}`}>{action.priority}</span></div>)}</div></article><article className="surface-card p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Development pulse</p><h3 className="text-lg font-semibold">Pipeline progress</h3></div><span className="text-2xl font-semibold text-emerald-600">{avgProgress}%</span></div><div className="progress-track progress-emerald mt-5"><div style={{ width: `${avgProgress}%` }}/></div><div className="mt-4 grid grid-cols-3 gap-2 text-center text-xs text-slate-500"><span><strong className="block text-lg text-slate-800">{features.length}</strong>items</span><span><strong className="block text-lg text-slate-800">{features.filter((feature: Feature) => feature.progress === 100).length}</strong>complete</span><span><strong className="block text-lg text-slate-800">{meetings.filter((meeting: Meeting) => Date.parse(meeting.scheduled_for) > Date.now()).length}</strong>upcoming</span></div></article></div></section>; }

// Final dashboard presentation: compact visual layout with calendar as the primary surface.
