DashboardModule = function VisualDashboardWrapper(props: any) { return <VisualDashboardModule {...props}/>; };

function BalancedDashboardModule({ clients, clientId, setClientId, selectedName, data, setMeetingDate }: any) { const [month, setMonth] = useState(() => new Date(new Date().getFullYear(), new Date().getMonth(), 1)); const [selectedDate, setSelectedDate] = useState(""); const meetings = data.meetings.filter((meeting: Meeting) => !clientId || String(meeting.client_id) === clientId); const actions = data.actions.filter((action: Action) => !clientId || String(action.client_id) === clientId); const features = data.features.filter((feature: Feature) => !clientId || String(feature.client_id) === clientId); const open = actions.filter((action: Action) => !["done", "completed", "closed"].includes((action.status || "").toLowerCase())); const statuses = ["Open", "In Progress", "Blocked", "Testing", "Completed"]; const countStatus = (status: string) => actions.filter((action: Action) => status === "Completed" ? ["done", "completed", "closed"].includes((action.status || "").toLowerCase()) : (action.status || "").toLowerCase() === status.toLowerCase()).length; const dateKey = (day: Date) => `${day.getFullYear()}-${String(day.getMonth() + 1).padStart(2, "0")}-${String(day.getDate()).padStart(2, "0")}`; const dates = new Set(meetings.map((meeting: Meeting) => meeting.scheduled_for.slice(0, 10))); const leading = new Date(month.getFullYear(), month.getMonth(), 1).getDay(); const days = new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate(); const cells = Array.from({ length: leading + days }, (_, index) => index < leading ? null : new Date(month.getFullYear(), month.getMonth(), index - leading + 1)); const avg = features.length ? Math.round(features.reduce((total: number, feature: Feature) => total + feature.progress, 0) / features.length) : 0; const selectDate = (date: string) => { setSelectedDate(date); setMeetingDate(date); }; return <section className="mt-6"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Delivery dashboard</p><h2 className="text-3xl font-semibold tracking-tight">{selectedName || "Portfolio overview"}</h2><p className="mt-1 text-sm text-slate-500">A visual snapshot of delivery health and current priorities.</p></div><label className="module-filters">Client<select value={clientId} onChange={event => setClientId(event.target.value)}><option value="">All clients</option>{clients.map((client: Client) => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label></div><div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><SummaryCard label="Meetings" value={meetings.length} tone="indigo"/><SummaryCard label="Open actions" value={open.length} tone="amber"/><SummaryCard label="Development progress" value={`${avg}%`} tone="emerald"/><SummaryCard label="Completed actions" value={countStatus("Completed")} tone="violet"/></div><div className="mt-6 grid gap-5 lg:grid-cols-[1.35fr_.85fr]"><article className="surface-card p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Delivery pulse</p><h3 className="text-lg font-semibold">Action status</h3></div><span className="soft-pill">{actions.length} total</span></div><div className="mt-5 space-y-4">{statuses.map(status => <div key={status}><div className="flex justify-between text-sm"><span>{status}</span><strong>{countStatus(status)}</strong></div><div className="progress-track mt-1"><div className={`status-bar status-bar-${status.toLowerCase().replace(" ", "-")}`} style={{ width: `${actions.length ? countStatus(status) / actions.length * 100 : 0}%` }}/></div></div>)}</div><div className="mt-6 border-t border-slate-100 pt-5"><div className="flex items-center justify-between"><p className="eyebrow">Development pipeline</p><span className="text-sm font-semibold text-emerald-600">{avg}%</span></div><div className="progress-track progress-emerald mt-2"><div style={{ width: `${avg}%` }}/></div><div className="mt-3 grid gap-2 sm:grid-cols-2">{features.slice(0, 4).map((feature: Feature) => <div className="dashboard-feature" key={feature.id}><div className="flex justify-between text-xs"><span className="truncate">{feature.name}</span><strong>{feature.progress}%</strong></div><div className="progress-track mt-1"><div className="bg-indigo-500" style={{ width: `${feature.progress}%` }}/></div></div>)}</div></div></article><article className="surface-card p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Priority queue</p><h3 className="text-lg font-semibold">Next actions</h3></div><span className="soft-pill">{open.length}</span></div><div className="mt-4 space-y-2">{open.slice(0, 6).map((action: Action) => <div className="dashboard-action" key={action.id}><div><p className="font-medium">{action.title}</p><p className="text-xs text-slate-500">{action.owner || "Unassigned"}{action.due_date ? ` · Due ${action.due_date}` : ""}</p></div><span className={`priority-dot priority-${(action.priority || "medium").toLowerCase()}`}>{action.priority}</span></div>)}</div></article></div><div className="mt-5 grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><article className="surface-card p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Schedule</p><h3 className="font-semibold">{month.toLocaleDateString(undefined, { month: "long", year: "numeric" })}</h3></div><div className="flex gap-1"><button type="button" className="calendar-nav" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() - 1, 1))}>‹</button><button type="button" className="calendar-nav" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() + 1, 1))}>›</button></div></div><div className="calendar-weekdays mt-4">{["S", "M", "T", "W", "T", "F", "S"].map((day, index) => <span key={`${day}-${index}`}>{day}</span>)}</div><div className="compact-calendar-grid">{cells.map((day, index) => day ? <button type="button" key={dateKey(day)} className={`compact-calendar-day ${dates.has(dateKey(day) ? dateKey(day) : "") ? "has-meeting" : ""} ${selectedDate === dateKey(day) ? "is-selected" : ""}`} onClick={() => dates.has(dateKey(day)) && selectDate(dateKey(day))}>{day.getDate()}</button> : <span key={`blank-${index}`}/>)}</div><p className="mt-3 text-xs text-slate-500">{dates.size} meeting dates highlighted</p></article><article className="surface-card p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Meeting activity</p><h3 className="font-semibold">{selectedDate ? new Date(`${selectedDate}T00:00:00`).toLocaleDateString() : "Upcoming and recent"}</h3></div><span className="soft-pill">{selectedDate ? meetings.filter((meeting: Meeting) => meeting.scheduled_for.slice(0, 10) === selectedDate).length : meetings.slice(0, 5).length}</span></div><div className="mt-4 grid gap-3 sm:grid-cols-2">{(selectedDate ? meetings.filter((meeting: Meeting) => meeting.scheduled_for.slice(0, 10) === selectedDate) : meetings.slice(0, 5)).map((meeting: Meeting) => <div className="calendar-meeting-card" key={meeting.id}><div className="flex justify-between gap-2"><p className="font-medium">{meeting.title}</p><span className="text-xs text-slate-500">{new Date(meeting.scheduled_for).toLocaleDateString()}</span></div><p className="mt-1 line-clamp-1 text-xs text-slate-500">{meeting.agenda || "No agenda recorded"}</p></div>)}</div>{!meetings.length && <p className="mt-4 text-sm text-slate-500">No meetings recorded yet.</p>}</article></div></section>; }

// Dashboard presentation: delivery metrics lead; calendar is a compact supporting widget.
