DashboardModule = function BalancedDashboardWrapper(props: any) { return <BalancedDashboardModule {...props}/>; };

function LeadershipRing({ progress, label, status }: { progress: number; label: string; status: string }) { const color = status === "critical" ? "#ef4444" : status === "warning" ? "#eab308" : "#22c55e"; const radius = 30; const circumference = 2 * Math.PI * radius; return <div className="leadership-ring-card"><div className="relative"><svg width="78" height="78" className="-rotate-90"><circle cx="39" cy="39" r={radius} fill="none" stroke="#e5e7eb" strokeWidth="8"/><circle cx="39" cy="39" r={radius} fill="none" stroke={color} strokeWidth="8" strokeDasharray={circumference} strokeDashoffset={circumference - progress / 100 * circumference} strokeLinecap="round"/></svg><strong className="leadership-ring-value">{progress}%</strong></div><span title={label}>{label}</span><i style={{ backgroundColor: color }}/></div>; }

function ExecutiveVisualModule() { const [dashboard, setDashboard] = useState<any>(null); const [restricted, setRestricted] = useState(false); useEffect(() => { apiFetch("/dashboards/executive").then(response => response.ok ? response.json() : Promise.reject()).then(setDashboard).catch(() => setRestricted(true)); }, []); if (restricted) return <article className="surface-card mt-6 p-8 text-center text-slate-600">Executive Dashboard is restricted to administrators and management.</article>; if (!dashboard) return <article className="surface-card mt-6 p-8 text-center text-slate-500">Loading Executive Pulse…</article>; const summary = dashboard.summary; const statusData = [{ name: "Completed", value: summary.total_completed, color: "#22c55e" }, { name: "Open", value: Math.max(0, summary.total_action_items - summary.total_completed), color: "#3b82f6" }]; const workload = (dashboard.team_workload || []).map((item: any) => ({ name: item.user_name, tasks: item.task_count })); return <section className="mt-6"><div className="flex items-end justify-between"><div><p className="eyebrow">Leadership view</p><h2 className="text-3xl font-semibold tracking-tight">Executive Pulse</h2><p className="mt-1 text-sm text-slate-500">Portfolio health at a glance.</p></div><span className="soft-pill">Live overview</span></div><div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><SummaryCard label="Projects" value={summary.total_projects} tone="indigo"/><SummaryCard label="Open tasks" value={Math.max(0, summary.total_action_items - summary.total_completed)} tone="blue"/><SummaryCard label="Overdue" value={summary.overdue} tone="rose"/><SummaryCard label="Blocked" value={summary.blocked} tone="amber"/></div><div className="mt-6 grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><article className="surface-card p-5"><p className="eyebrow">Task status</p><div className="h-52"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={statusData} dataKey="value" innerRadius={52} outerRadius={72} paddingAngle={3}>{statusData.map((item: any) => <Cell key={item.name} fill={item.color}/>)}</Pie><Tooltip/><Legend verticalAlign="bottom" height={28}/></PieChart></ResponsiveContainer></div><p className="text-center text-xs text-slate-500">{summary.overall_progress}% overall completion</p></article><article className="surface-card p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Project health</p><h3 className="text-lg font-semibold">Portfolio progress</h3></div><span className="soft-pill">{dashboard.project_health.length} projects</span></div><div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-3 xl:grid-cols-4">{dashboard.project_health.map((project: any) => <LeadershipRing key={project.project_id} progress={project.progress} label={project.project_name} status={project.health}/>)}</div></article></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><article className="surface-card p-5"><p className="eyebrow">Team workload</p><div className="mt-3 h-56">{workload.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={workload} layout="vertical" margin={{ left: 10, right: 12 }}><XAxis type="number" hide/><YAxis type="category" dataKey="name" width={90} tick={{ fontSize: 11 }}/><Tooltip/><Bar dataKey="tasks" fill="#8b5cf6" radius={[0, 5, 5, 0]}/></BarChart></ResponsiveContainer> : <p className="pt-8 text-center text-sm text-slate-500">No active assignments.</p>}</div></article><article className="surface-card p-5"><div className="flex items-center justify-between"><p className="eyebrow">Recent activity</p><span className="soft-pill">Last updates</span></div><div className="mt-3 space-y-2">{(dashboard.recent_activity || []).slice(0, 6).map((item: any) => <div className="dashboard-action" key={item.id}><span className="truncate">{item.title}</span><span className="soft-pill">{item.status}</span></div>)}{!dashboard.recent_activity?.length && <p className="text-sm text-slate-500">No recent activity.</p>}</div></article></div></section>; }

function MasterVisualModule() { const [dashboard, setDashboard] = useState<any>(null); const [restricted, setRestricted] = useState(false); useEffect(() => { apiFetch("/dashboards/master").then(response => response.ok ? response.json() : Promise.reject()).then(setDashboard).catch(() => setRestricted(true)); }, []); if (restricted) return <article className="surface-card mt-6 p-8 text-center text-slate-600">Master Control is restricted to NorQ internal management.</article>; if (!dashboard) return <article className="surface-card mt-6 p-8 text-center text-slate-500">Loading Master Control…</article>; const summary = dashboard.summary; return <section className="mt-6"><div><p className="eyebrow">Operations view</p><h2 className="text-3xl font-semibold tracking-tight">Master Control Tower</h2><p className="mt-1 text-sm text-slate-500">Operational pulse across every client project.</p></div><div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><SummaryCard label="Projects" value={summary.total_projects} tone="indigo"/><SummaryCard label="Open tasks" value={summary.open_tasks} tone="blue"/><SummaryCard label="Overdue" value={summary.overdue} tone="rose"/><SummaryCard label="Critical" value={summary.critical} tone="amber"/><SummaryCard label="Total tasks" value={summary.total_tasks} tone="violet"/></div><article className="surface-card mt-6 p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Project pulse</p><h3 className="text-lg font-semibold">Health by project</h3></div><span className="soft-pill">{dashboard.projects.length} active</span></div><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{dashboard.projects.map((project: any) => <div className={`master-project-card ${project.overdue > 5 || project.blocked > 3 ? "master-project-critical" : project.overdue > 2 || project.blocked > 1 ? "master-project-warning" : ""}`} key={project.id}><div className="flex items-start justify-between gap-2"><div><p className="font-semibold">{project.name}</p><p className="text-xs text-slate-500">{project.client}</p></div><strong>{project.progress}%</strong></div><div className="progress-track mt-3"><div style={{ width: `${project.progress}%` }}/></div><div className="mt-3 flex justify-between text-xs text-slate-500"><span>{project.completed}/{project.total} complete</span><span className="text-rose-600">{project.overdue} overdue</span></div></div>)}</div></article><div className="mt-5 grid gap-5 lg:grid-cols-3"><article className="surface-card p-5"><p className="eyebrow">Urgent actions</p><div className="mt-3 space-y-2">{dashboard.urgent_actions.slice(0, 7).map((item: any) => <div className="dashboard-action" key={item.id}><span className="truncate">{item.title}</span><span className="priority-dot priority-high">{item.priority}</span></div>)}{!dashboard.urgent_actions.length && <p className="text-sm text-slate-500">No urgent actions.</p>}</div></article><article className="surface-card p-5"><p className="eyebrow">Deadlines</p><div className="mt-3 space-y-2">{dashboard.upcoming_deadlines.slice(0, 7).map((item: any) => <div className="dashboard-action" key={item.id}><span className="truncate">{item.title}</span><span className="soft-pill">{item.eda}</span></div>)}{!dashboard.upcoming_deadlines.length && <p className="text-sm text-slate-500">No deadlines in the next 14 days.</p>}</div></article><article className="surface-card p-5"><p className="eyebrow">Resource load</p><div className="mt-3 space-y-3">{dashboard.resource_allocation.slice(0, 7).map((item: any) => <div key={item.user_id}><div className="flex justify-between text-xs"><span>{item.user_name}</span><strong>{item.task_count}</strong></div><div className="progress-track mt-1"><div className={item.task_count > 10 ? "bg-rose-500" : item.task_count > 5 ? "bg-amber-500" : "bg-emerald-500"} style={{ width: `${Math.min(100, item.task_count / 15 * 100)}%` }}/></div></div>)}{!dashboard.resource_allocation.length && <p className="text-sm text-slate-500">No active assignments.</p>}</div></article></div></section>; }

// Leadership redesign: visual command centres replace table-heavy presentations.
// @ts-ignore Runtime presentation replacement.
ExecutiveDashboardModule = function ExecutiveVisualWrapper() { return <ExecutiveVisualModule/>; };
// @ts-ignore Runtime presentation replacement.
MasterControlModule = function MasterVisualWrapper() { return <MasterVisualModule/>; };
function QAWorkspaceModule() {
  const [bugs, setBugs] = useState<any[]>([]); const [clients, setClients] = useState<Client[]>([]); const [filter, setFilter] = useState({ client: "", status: "", severity: "" }); const [notice, setNotice] = useState("");
  const load = () => Promise.all([apiFetch("/bugs"), apiFetch("/clients")]).then(async ([bugsResponse, clientsResponse]) => { setBugs(bugsResponse.ok ? await bugsResponse.json() : []); setClients(clientsResponse.ok ? await clientsResponse.json() : []); }).catch(() => setNotice("Could not load the QA workspace."));
  useEffect(() => { load(); }, []);
  const create = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const payload = Object.fromEntries(form.entries()); const response = await apiFetch("/bugs", { method: "POST", body: JSON.stringify({ ...payload, client_id: Number(payload.client_id) }) }); if (!response.ok) { setNotice("Could not create the bug."); return; } event.currentTarget.reset(); setNotice("Bug added to the QA queue."); load(); };
  const update = async (bug: any, field: string, value: string) => { const response = await apiFetch(`/bugs/${bug.id}`, { method: "PATCH", body: JSON.stringify({ [field]: value }) }); if (response.ok) setBugs(previous => previous.map(item => item.id === bug.id ? { ...item, [field]: value } : item)); };
  const remove = async (bug: any) => { if (!window.confirm(`Delete ${bug.title}?`)) return; const response = await apiFetch(`/bugs/${bug.id}`, { method: "DELETE" }); if (response.ok) setBugs(previous => previous.filter(item => item.id !== bug.id)); };
  const importFile = async (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const body = new FormData(); body.append("file", file); const response = await apiFetch("/bugs/import", { method: "POST", body }); const result = await response.json().catch(() => null); setNotice(response.ok ? `Imported ${result?.created || 0} bugs (${result?.skipped || 0} skipped).` : result?.detail || "Import failed."); if (response.ok) load(); event.target.value = ""; };
  const downloadTemplate = async () => { const response = await apiFetch("/bugs/import-template"); if (!response.ok) { setNotice("Could not download the import template."); return; } const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = "delivery-hub-bugs-template.csv"; link.click(); URL.revokeObjectURL(url); };
  const visible = bugs.filter(bug => (!filter.client || String(bug.client_id) === filter.client) && (!filter.status || bug.status === filter.status) && (!filter.severity || bug.severity === filter.severity));
  return <section className="mt-6"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">QA workspace</p><h2 className="text-2xl font-semibold tracking-tight">Bug tracker</h2><p className="mt-1 text-sm text-slate-500">Log, triage, assign, import and close bugs without leaving the delivery workspace.</p></div><label className="upload-button">Import CSV / Excel<input type="file" accept=".csv,.xlsx,.xls" onChange={importFile}/></label></div>{notice && <p className="notice mt-4">{notice}</p>}<div className="mt-5 grid gap-4 sm:grid-cols-3"><SummaryCard label="Total bugs" value={bugs.length} tone="indigo"/><SummaryCard label="Open bugs" value={bugs.filter(bug => bug.status !== "Fixed" && bug.status !== "Closed").length} tone="amber"/><SummaryCard label="Critical" value={bugs.filter(bug => bug.severity === "Critical").length} tone="rose"/></div><form className="surface-card mt-6 p-5" onSubmit={create}><div className="flex items-center justify-between"><div><p className="eyebrow">New bug</p><h3 className="text-lg font-semibold">Add an issue</h3></div></div><div className="mt-4 grid gap-3 md:grid-cols-4"><label>Client<select name="client_id" required defaultValue=""> <option value="" disabled>Select client</option>{clients.map(client => <option key={client.id} value={client.id}>{client.name}</option>)}</select></label><label className="md:col-span-2">Title<input name="title" required placeholder="Describe the issue"/></label><label>Module<input name="module" required placeholder="Web portal"/></label><label>Severity<select name="severity" defaultValue="Medium"><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select></label><label>Assigned developer<input name="assigned_developer" placeholder="Developer name"/></label><label>QA owner<input name="qa_owner" placeholder="QA owner"/></label><label>Status<select name="status" defaultValue="Open"><option>Open</option><option>In Progress</option><option>Testing</option><option>Fixed</option><option>Closed</option></select></label><label>Target fix date<input name="target_fix_date" type="date"/></label></div><button className="mt-4">Add bug</button></form><div className="surface-card mt-6 overflow-hidden"><div className="flex flex-col gap-3 border-b border-slate-100 p-5 sm:flex-row sm:items-end sm:justify-between"><div><p className="eyebrow">Bug queue</p><h3 className="text-lg font-semibold">{visible.length} issues shown</h3></div><div className="module-filters"><label>Client<select value={filter.client} onChange={event => setFilter({ ...filter, client: event.target.value })}><option value="">All</option>{clients.map(client => <option key={client.id} value={client.id}>{client.name}</option>)}</select></label><label>Status<select value={filter.status} onChange={event => setFilter({ ...filter, status: event.target.value })}><option value="">All</option><option>Open</option><option>In Progress</option><option>Testing</option><option>Fixed</option><option>Closed</option></select></label><label>Severity<select value={filter.severity} onChange={event => setFilter({ ...filter, severity: event.target.value })}><option value="">All</option><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select></label></div></div><div className="overflow-x-auto"><table><thead><tr><th>Bug</th><th>Module</th><th>Severity</th><th>Owner</th><th>Status</th><th>Fix date</th><th></th></tr></thead><tbody>{visible.map(bug => <tr key={bug.id}><td><p className="font-medium">{bug.title}</p><p className="text-xs text-slate-500">{clients.find(client => client.id === bug.client_id)?.name || "Unknown client"}</p></td><td>{bug.module}</td><td><span className={`priority-dot priority-${String(bug.severity).toLowerCase()}`}>{bug.severity}</span></td><td>{bug.assigned_developer || "Unassigned"}</td><td><select value={bug.status} onChange={event => update(bug, "status", event.target.value)}><option>Open</option><option>In Progress</option><option>Testing</option><option>Fixed</option><option>Closed</option></select></td><td>{bug.target_fix_date || "—"}</td><td><button type="button" className="delete-button" onClick={() => remove(bug)}>Delete</button></td></tr>)}</tbody></table>{!visible.length && <p className="p-8 text-center text-sm text-slate-500">No bugs match the current filters.</p>}</div></div><p className="mt-4 text-xs text-slate-500">Import columns: client_id, title, module, severity, assigned_developer, qa_owner, status, target_fix_date. Excel files require the backend Excel dependency.</p></section>;
}
