function QAExecutiveSummaryModule() {
  const [bugs, setBugs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  useEffect(() => {
    apiFetch("/bugs").then(response => response.ok ? response.json() : Promise.reject()).then(payload => setBugs(Array.isArray(payload) ? payload : [])).catch(() => setError(true)).finally(() => setLoading(false));
  }, []);
  const normalizedStatus = (bug: any) => String(bug.status || "").trim().toLowerCase();
  const count = (statuses: string[]) => bugs.filter(bug => statuses.includes(normalizedStatus(bug))).length;
  const workload = (field: "assigned_developer" | "qa_owner") => {
    const people = new Map<string, { total: number; open: number; inProgress: number; toDo: number }>();
    bugs.forEach(bug => {
      const name = String(bug[field] || "Unassigned");
      const current = people.get(name) || { total: 0, open: 0, inProgress: 0, toDo: 0 };
      const status = normalizedStatus(bug);
      current.total += 1;
      if (status === "open") current.open += 1;
      if (["in progress", "in-progress"].includes(status)) current.inProgress += 1;
      if (["to do", "todo"].includes(status)) current.toDo += 1;
      people.set(name, current);
    });
    return Array.from(people.entries()).sort((left, right) => right[1].total - left[1].total);
  };
  if (error) return <article className="surface-card mt-6 p-8 text-center text-slate-600">Could not load Jira executive visibility data.</article>;
  if (loading) return <article className="surface-card mt-6 p-8 text-center text-slate-500">Loading executive QA summary…</article>;
  const renderWorkload = (title: string, rows: ReturnType<typeof workload>) => <article className="surface-card overflow-hidden"><div className="border-b border-slate-100 p-5"><p className="eyebrow">{title}</p><h3 className="text-lg font-semibold">Workload by person</h3></div><div className="overflow-x-auto"><table><thead><tr><th>Person</th><th>Open</th><th>In Progress</th><th>To Do</th><th>Total</th></tr></thead><tbody>{rows.map(([name, values]) => <tr key={name}><td className="font-medium">{name}</td><td>{values.open}</td><td>{values.inProgress}</td><td>{values.toDo}</td><td><strong>{values.total}</strong></td></tr>)}</tbody></table>{!rows.length && <p className="p-8 text-center text-sm text-slate-500">No assignment data available.</p>}</div></article>;
  return <section className="mt-6"><div><p className="eyebrow">Executive QA visibility</p><h2 className="text-2xl font-semibold tracking-tight">Jira bug health</h2><p className="mt-1 text-sm text-slate-500">A high-level view of Jira workload and ownership. Bug records remain managed in Jira.</p></div><div className="mt-5 grid gap-4 sm:grid-cols-3"><SummaryCard label="Open" value={count(["open"])} tone="amber"/><SummaryCard label="In Progress" value={count(["in progress", "in-progress"])} tone="indigo"/><SummaryCard label="To Do" value={count(["to do", "todo"])} tone="violet"/></div><div className="mt-6 grid gap-5 lg:grid-cols-2">{renderWorkload("Assignee", workload("assigned_developer"))}{renderWorkload("Assigned to", workload("qa_owner"))}</div><p className="mt-4 text-xs text-slate-500">{bugs.length} total Jira issues represented in this summary.</p></section>;
}

