function QAExecutiveDataModule() {
  const [rows, setRows] = useState<any[]>([]); const [loading, setLoading] = useState(true); const [notice, setNotice] = useState("");
  const load = () => apiFetch("/qa-summary").then(response => response.ok ? response.json() : Promise.reject()).then(payload => setRows(Array.isArray(payload) ? payload : [])).catch(() => setNotice("Could not load the executive QA summary.")).finally(() => setLoading(false));
  useEffect(() => { load(); }, []);
  const total = (field: string) => rows.reduce((sum, row) => sum + Number(row[field] || 0), 0);
  const create = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const payload = { total_bugs: Number(form.get("total_bugs")), done: Number(form.get("done")), in_progress: Number(form.get("in_progress")), to_do: Number(form.get("to_do")), assignee: String(form.get("assignee") || ""), owner: String(form.get("owner") || "") }; const response = await apiFetch("/qa-summary", { method: "POST", body: JSON.stringify(payload) }); if (!response.ok) { setNotice("Could not add the QA summary row."); return; } event.currentTarget.reset(); setNotice("QA summary row added."); load(); };
  const importFile = async (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const body = new FormData(); body.append("file", file); const response = await apiFetch("/qa-summary/import", { method: "POST", body }); const result = await response.json().catch(() => null); setNotice(response.ok ? "QA summary imported and replaced." : result?.detail || "Could not import the QA summary."); if (response.ok) setRows(Array.isArray(result) ? result : []); event.target.value = ""; };
  const downloadTemplate = async () => { const response = await apiFetch("/qa-summary/template"); if (!response.ok) { setNotice("Could not download the QA summary template."); return; } const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = "delivery-hub-qa-summary-template.csv"; link.click(); URL.revokeObjectURL(url); };
  if (loading) return <article className="surface-card mt-6 p-8 text-center text-slate-500">Loading executive QA summary…</article>;
  return <section className="mt-6"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Executive QA visibility</p><h2 className="text-2xl font-semibold tracking-tight">QA health summary</h2><p className="mt-1 text-sm text-slate-500">Enter or bulk upload the high-level QA numbers executives need to see.</p></div><div className="flex flex-wrap gap-2"><button type="button" className="secondary-button" onClick={downloadTemplate}>Download template</button><label className="upload-button">Import CSV / Excel<input type="file" accept=".csv,.xlsx,.xls" onChange={importFile}/></label></div></div>{notice && <p className="notice mt-4">{notice}</p>}<div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><SummaryCard label="Total Bugs" value={total("total_bugs")} tone="indigo"/><SummaryCard label="Done" value={total("done")} tone="emerald"/><SummaryCard label="In Progress" value={total("in_progress")} tone="amber"/><SummaryCard label="To Do" value={total("to_do")} tone="violet"/></div><form className="surface-card mt-6 p-5" onSubmit={create}><div><p className="eyebrow">Manual update</p><h3 className="text-lg font-semibold">Add executive summary row</h3></div><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-6"><label>Total Bugs<input name="total_bugs" type="number" min="0" required defaultValue="0"/></label><label>Done<input name="done" type="number" min="0" required defaultValue="0"/></label><label>In Progress<input name="in_progress" type="number" min="0" required defaultValue="0"/></label><label>To Do<input name="to_do" type="number" min="0" required defaultValue="0"/></label><label>Assignee<input name="assignee" placeholder="Developer / team"/></label><label>Owner<input name="owner" placeholder="QA owner"/></label></div><button className="mt-4" type="submit">Add row</button></form><article className="surface-card mt-6 overflow-hidden"><div className="border-b border-slate-100 p-5"><p className="eyebrow">Ownership breakdown</p><h3 className="text-lg font-semibold">Assignee and Owner</h3></div><div className="overflow-x-auto"><table><thead><tr><th>Assignee</th><th>Owner</th><th>Total Bugs</th><th>Done</th><th>In Progress</th><th>To Do</th></tr></thead><tbody>{rows.map(row => <tr key={row.id}><td>{row.assignee || "Unassigned"}</td><td>{row.owner || "Unassigned"}</td><td>{row.total_bugs}</td><td>{row.done}</td><td>{row.in_progress}</td><td>{row.to_do}</td></tr>)}</tbody></table>{!rows.length && <p className="p-8 text-center text-sm text-slate-500">Add a row or import the executive QA template.</p>}</div></article></section>;
}

