function IndependentMeetingCard({ meeting, updateMeeting, deleteMeeting }: { meeting: Meeting; updateMeeting: (id: number, payload: Record<string, string>) => Promise<Meeting | null>; deleteMeeting: (id: number, title: string) => void }) {
  const date = new Date(meeting.scheduled_for); const editable = meeting.created_at ? Date.now() - Date.parse(meeting.created_at) <= 48 * 60 * 60 * 1000 : false; const [editing, setEditing] = useState(false); const [form, setForm] = useState({ title: meeting.title, scheduled_for: meeting.scheduled_for.slice(0, 16), attendees: meeting.attendees, agenda: meeting.agenda, notes: meeting.notes });
  useEffect(() => setForm({ title: meeting.title, scheduled_for: meeting.scheduled_for.slice(0, 16), attendees: meeting.attendees, agenda: meeting.agenda, notes: meeting.notes }), [meeting]);
  const save = async (event: FormEvent) => { event.preventDefault(); if (await updateMeeting(meeting.id, form)) setEditing(false); };
  return <article className="surface-card p-6"><div className="flex gap-4"><div className="meeting-date h-12 w-14 text-sm">{date.toLocaleDateString(undefined, { month: "short", day: "numeric" })}</div><div className="min-w-0 flex-1">{editing ? <form onSubmit={save} className="space-y-3"><div className="flex items-center justify-between gap-3"><input aria-label="Meeting title" value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} required/><button type="button" className="clear-filter" onClick={() => setEditing(false)}>Cancel</button></div><label>Date and time<input type="datetime-local" value={form.scheduled_for} onChange={event => setForm({ ...form, scheduled_for: event.target.value })} required/></label><label>Attendees<textarea value={form.attendees} onChange={event => setForm({ ...form, attendees: event.target.value })}/></label><label>Agenda<textarea value={form.agenda} onChange={event => setForm({ ...form, agenda: event.target.value })}/></label><label>Discussion points<textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })}/></label><button>Save changes</button></form> : <><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="text-lg font-semibold text-slate-900">{meeting.title}</h3><div className="flex items-center gap-2"><span className="text-xs text-slate-500">{date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</span><button type="button" className="edit-button" disabled={!editable} onClick={() => setEditing(true)}>{editable ? "Edit" : "Edit closed"}</button><button type="button" className="delete-button" onClick={() => deleteMeeting(meeting.id, meeting.title)}>Delete</button></div></div><p className="mt-1 text-sm text-slate-500">{meeting.attendees || "Attendees not recorded"}</p><div className="meeting-details"><Detail label="Agenda" value={meeting.agenda}/><Detail label="Discussion points" value={meeting.notes}/><DiscussionPoints meeting={meeting}/></div></>}</div></div></article>;
}

function IndependentMeetingsModule({ clients, clientId, setClientId, selectedName, data, meetingDate, setMeetingDate, submit, updateMeeting, deleteMeeting }: any) {
  const visibleMeetings = data.meetings.filter((meeting: Meeting) => (!clientId || String(meeting.client_id) === clientId) && (!meetingDate || meeting.scheduled_for.slice(0, 10) === meetingDate));
  return <><section className="mt-6 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Meeting module</p><h2 className="text-2xl font-semibold tracking-tight">Meeting history</h2><p className="mt-1 text-sm text-slate-500">Revisit agendas, discussion points, and meeting outcomes for {selectedName || "both client accounts"}.</p></div><div className="module-filters"><label>Client<select value={clientId} onChange={event => setClientId(event.target.value)}><option value="">All clients</option>{clients.map((client: Client) => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label><label className="date-filter">Meeting date<input aria-label="Filter meetings by date" type="date" value={meetingDate} onChange={event => setMeetingDate(event.target.value)}/></label>{(meetingDate || clientId) && <button className="clear-filter" onClick={() => { setMeetingDate(""); setClientId(""); }}>Clear</button>}<span className="soft-pill">{visibleMeetings.length} shown</span></div></section><section className="mt-5 grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><div><MeetingForm clients={clients} defaultClient={clientId} submit={submit}/></div><div className="space-y-4">{visibleMeetings.length ? visibleMeetings.map((meeting: Meeting) => <IndependentMeetingCard key={meeting.id} meeting={meeting} updateMeeting={updateMeeting} deleteMeeting={deleteMeeting}/>) : <article className="surface-card"><Empty icon="◷" title={meetingDate || clientId ? "No meetings match these filters" : "No meeting history yet"} text={meetingDate || clientId ? "Clear or change the filters to view other meetings." : "Create your first meeting to build a searchable record."}/></article>}</div></section></>;
}

// Meetings are intentionally independent; action items live only in the Action items module.
// @ts-ignore Runtime presentation replacement.
MeetingsModule = function IndependentMeetingsWrapper(props: any) { return <IndependentMeetingsModule {...props}/>; };

function DynamicDevelopmentModule({ clients, clientId, setClientId, selectedName, features, setData, setNotice, submit, updateProgress, deleteFeature }: any) {
  const [sprintFilter, setSprintFilter] = useState(""); const [statusFilter, setStatusFilter] = useState(""); const [editing, setEditing] = useState<Feature | null>(null); const [draft, setDraft] = useState<Feature | null>(null);
  const sprints = Array.from(new Set<string>(features.map((feature: Feature) => feature.sprint))).sort(); const visibleFeatures = features.filter((feature: Feature) => (!clientId || String(feature.client_id) === clientId) && (!sprintFilter || feature.sprint === sprintFilter) && (!statusFilter || (statusFilter === "complete" ? feature.progress === 100 : feature.progress < 100)));
  const beginEdit = (feature: Feature) => { setEditing(feature); setDraft({ ...feature }); };
  const save = async (event: FormEvent) => { event.preventDefault(); if (!draft) return; const response = await apiFetch(`/features/${draft.id}`, { method: "PATCH", body: JSON.stringify({ client_id: Number(draft.client_id), name: draft.name, developer: draft.developer, sprint: draft.sprint, progress: Number(draft.progress), target_date: draft.target_date, dependency: draft.dependency || null }) }); const result = await response.json().catch(() => null); if (!response.ok) { setNotice(result?.detail || "Could not update the development item."); return; } setData((previous: Dashboard) => ({ ...previous, features: previous.features.map(item => item.id === result.id ? result : item) })); setEditing(null); setDraft(null); setNotice("Development item updated."); };
  return <section className="mt-6"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Development module</p><h2 className="text-2xl font-semibold tracking-tight">Development pipeline</h2><p className="mt-1 text-sm text-slate-500">Edit delivery items at any time. Due dates indicate schedule health but never block updates for {selectedName || "both client accounts"}.</p></div><div className="module-filters"><label>Client<select value={clientId} onChange={event => setClientId(event.target.value)}><option value="">All clients</option>{clients.map((client: Client) => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label><label>Pipeline / sprint<select value={sprintFilter} onChange={event => setSprintFilter(event.target.value)}><option value="">All sprints</option>{sprints.map((sprint: string) => <option value={sprint} key={sprint}>{sprint}</option>)}</select></label><label>Status<select value={statusFilter} onChange={event => setStatusFilter(event.target.value)}><option value="">All statuses</option><option value="active">Active</option><option value="complete">Complete</option></select></label><span className="soft-pill">{visibleFeatures.length} shown</span></div></div><section className="mt-5 grid gap-6 lg:grid-cols-[.72fr_1.28fr]"><FeatureForm clients={clients} defaultClient={clientId} submit={submit}/><div className="space-y-4">{visibleFeatures.length ? visibleFeatures.map((feature: Feature) => <div key={feature.id} className="relative"><button type="button" className="edit-button absolute right-6 top-6 z-10" onClick={() => beginEdit(feature)}>Edit item</button><FeatureCard feature={feature} updateProgress={updateProgress} deleteFeature={deleteFeature}/></div>) : <article className="surface-card"><Empty icon="↗" title={features.length ? "No pipeline items match these filters" : "Your pipeline is clear"} text={features.length ? "Clear or change the filters to view other development items." : "Add a development item with a due date to begin tracking delivery."}/></article>}</div></section>{editing && draft && <div className="modal-backdrop"><form className="modal-card space-y-4" onSubmit={save}><div className="flex items-center justify-between"><div><p className="eyebrow">Development item</p><h3 className="text-lg font-semibold">Edit delivery item</h3></div><button type="button" className="clear-filter" onClick={() => { setEditing(null); setDraft(null); }}>Close</button></div><label>Client<select value={draft.client_id} onChange={event => setDraft({ ...draft, client_id: Number(event.target.value) })}>{clients.map((client: Client) => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label><label>Name<input value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })} required/></label><div className="grid gap-3 sm:grid-cols-2"><label>Developer<input value={draft.developer} onChange={event => setDraft({ ...draft, developer: event.target.value })} required/></label><label>Sprint<input value={draft.sprint} onChange={event => setDraft({ ...draft, sprint: event.target.value })} required/></label></div><div className="grid gap-3 sm:grid-cols-2"><label>Progress (%)<input type="number" min="0" max="100" value={draft.progress} onChange={event => setDraft({ ...draft, progress: Number(event.target.value) })} required/></label><label>Due date<input type="date" value={draft.target_date} onChange={event => setDraft({ ...draft, target_date: event.target.value })} required/></label></div><label>Dependency<input value={draft.dependency || ""} onChange={event => setDraft({ ...draft, dependency: event.target.value })} placeholder="Optional dependency"/></label><button type="submit">Save changes</button></form></div>}</section>;
}

// Development items remain editable after their due date; overdue is informational only.
// @ts-ignore Runtime presentation replacement.
DevelopmentModule = function DynamicDevelopmentWrapper(props: any) {
  const refreshData = (updater: any) => { if (props.setData) props.setData(updater); if (typeof window !== "undefined") window.dispatchEvent(new Event("deliveryhub-refresh")); };
  return <DynamicDevelopmentModule {...props} setData={refreshData} setNotice={props.setNotice || (() => undefined)}/>;
};

// Replace the legacy HTML5 drag surface with the touch-aware Kanban board.
// @ts-ignore Runtime presentation replacement.
const LegacyActionItemsModule = ActionItemsModule;
// @ts-ignore
ActionItemsModule = function ActionItemsKanbanWrapper(props: any) { const updateStatus = async (id: number, status: string) => { const item = props.actions.find((action: Action) => action.id === id); if (!item) return false; const response = await apiFetch(`/action-items/${id}`, { method: "PATCH", body: JSON.stringify({ title: item.title, owner: item.owner, due_date: item.due_date || null, priority: item.priority, status, meeting_id: item.meeting_id }) }); if (!response.ok) { props.setNotice("Could not update the action item."); return false; } const updated = await response.json(); props.setData((previous: Dashboard) => ({ ...previous, actions: previous.actions.map(action => action.id === id ? updated : action) })); props.setNotice("Action item moved."); return true; }; return <><LegacyActionItemsModule {...props}/><section className="kanban-modern-section"><div className="flex items-center justify-between"><div><p className="eyebrow">Responsive board</p><h3 className="text-lg font-semibold">Drag items between stages</h3></div><span className="text-xs text-slate-500">Touch and hold on mobile</span></div><KanbanBoard initialItems={props.actions} onStatusChange={updateStatus}/></section></>; };
